INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('bab072fd-ad85-5174-a997-e628bce993d3', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 7, 7, 'A tracer solution holds 3.0 × 10¹⁵ radioactive nuclei, each with a probability of 2.0 × 10⁻⁹ of decaying per second. What is the activity of the solution?', NULL, 1, 'numeric'::answer_type, '6e6', 'Bq', false, NULL, false, NULL, 'A = λN = 2.0 × 10⁻⁹ × 3.0 × 10¹⁵ = 6.0 × 10⁶ Bq. Mark scheme (2 marks). C1: A = λN. A1: A = 6.0 × 10⁶ Bq.', 2, NULL, NULL),
('43116c33-7c2f-527e-8e86-2f77bbf3c6cc', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 8, 8, 'Radioactive decay is described as spontaneous. What does this mean?', NULL, 1, 'multiple_choice'::answer_type, 'It is not affected by external conditions such as temperature or pressure', NULL, false, NULL, false, NULL, 'Decay depends only on the nucleus itself. Mark scheme (1 mark). B1: C (It is not affected by external conditions such as temperature or pressure).', 1, NULL, NULL),
('fa65a415-ad3b-52a7-a23b-0ca82aec9c8d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 9, 9, 'A source has an activity of 4.5 × 10⁴ Bq and a decay constant of 1.5 × 10⁻⁵ s⁻¹. How many undecayed nuclei does it contain?', NULL, 1, 'numeric'::answer_type, '3e9', NULL, false, NULL, false, NULL, 'N = A/λ = 4.5 × 10⁴ ÷ 1.5 × 10⁻⁵ = 3.0 × 10⁹. Mark scheme (2 marks). C1: N = A/λ. A1: N = 3.0 × 10⁹.', 2, NULL, NULL),
('6a2fbab7-ee9a-5d2b-80e0-14275531112c', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 10, 10, 'Which of these is equal to an activity of one becquerel?', NULL, 1, 'multiple_choice'::answer_type, 'One decay per second', NULL, false, NULL, false, NULL, 'Activity is the number of decays per unit time. Mark scheme (1 mark). B1: A (One decay per second).', 1, NULL, NULL),
('94f771e4-fe37-537a-bb93-8f705862bff0', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 11, 11, 'A sample of 6.0 × 10¹⁰ nuclei has an activity of 2.4 × 10³ Bq. Calculate the decay constant.', NULL, 1, 'numeric'::answer_type, '4e-8', 's⁻¹', false, NULL, false, NULL, 'λ = A/N = 2.4 × 10³ ÷ 6.0 × 10¹⁰ = 4.0 × 10⁻⁸ s⁻¹. Mark scheme (2 marks). C1: λ = A/N. A1: λ = 4.0 × 10⁻⁸ s⁻¹.', 2, NULL, NULL),
('ce9596cb-a300-5938-b71a-bf49dcea0e65', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 12, 12, 'What does the decay constant λ of an isotope represent?', NULL, 1, 'multiple_choice'::answer_type, 'The probability per unit time that any one nucleus decays', NULL, false, NULL, false, NULL, 'For a large sample, A = λN. Mark scheme (1 mark). B1: D (The probability per unit time that any one nucleus decays).', 1, NULL, NULL),
('a9762f3b-69f4-5bde-b246-a30aeec9a35a', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 13, 13, 'A detector records 85 counts per minute near a source, and 20 counts per minute with the source removed. Calculate the corrected count rate in counts per minute.', NULL, 1, 'numeric'::answer_type, '65', 'counts per minute', false, NULL, false, NULL, 'Corrected = 85 − 20 = 65 counts per minute. Mark scheme (2 marks). C1: subtract background. A1: count rate = 65 counts per minute.', 2, NULL, NULL),
('6c032029-8c42-58fe-84ac-43ec1a5fbc9f', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 14, 14, 'Radioactive decay is random. What does this mean?', NULL, 1, 'multiple_choice'::answer_type, 'It is impossible to predict which nucleus will decay next or when', NULL, false, NULL, false, NULL, 'Only the probability of decay is fixed. Mark scheme (1 mark). B1: B (It is impossible to predict which nucleus will decay next or when).', 1, NULL, NULL),
('5320e700-e2cf-565d-81c0-bcc4b0adf5b2', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 15, 15, 'An isotope has a decay constant of 0.020 s⁻¹. What is the percentage chance that a particular nucleus decays in the next second?', NULL, 1, 'numeric'::answer_type, '2', '%', false, NULL, false, NULL, 'Probability per second = λ: 0.020 × 100 = 2.0 %. Mark scheme (2 marks). C1: probability per second = λ. A1: probability = 2.0%.', 2, NULL, NULL),
('829c9250-5276-557f-80a6-96b3206a5917', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 16, 16, 'Repeated counts from a steady source over equal times give slightly different results. Why?', NULL, 1, 'multiple_choice'::answer_type, 'Radioactive decay is random', NULL, false, NULL, false, NULL, 'Random processes fluctuate about a mean. Mark scheme (1 mark). B1: C (Radioactive decay is random).', 1, NULL, NULL),
('64a94a99-5873-55c7-b6f5-91dbfc495b6b', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 17, 17, 'A source has a steady activity of 500 Bq. How many decays occur in 10 s?', NULL, 1, 'numeric'::answer_type, '5000', NULL, false, NULL, false, NULL, 'Decays = A × t = 500 × 10 = 5000. Mark scheme (2 marks). C1: decays = activity × time. A1: decays = 5000.', 2, NULL, NULL),
('ddf328a1-ef4c-5c9a-819c-cad3987d7238', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 18, 18, 'A detector''s count rate from a source is less than the source''s activity. Why?', NULL, 1, 'multiple_choice'::answer_type, 'Radiation goes off in all directions and not all of it entering the detector is detected', NULL, false, NULL, false, NULL, 'Only a fraction of emissions reach and register in the detector. Mark scheme (1 mark). B1: A (Radiation goes off in all directions and not all of it entering the detector is detected).', 1, NULL, NULL),
('7609f094-9ccf-587e-9027-d834bb55d7a5', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 19, 19, 'A source undergoes 2.4 × 10⁵ decays each minute. Calculate its activity in Bq.', NULL, 1, 'numeric'::answer_type, '4000', 'Bq', false, NULL, false, NULL, 'A = 2.4 × 10⁵ ÷ 60 = 4000 Bq. Mark scheme (2 marks). C1: per second. A1: A = 4000 Bq.', 2, NULL, NULL),
('1880bbe8-64fb-51f6-b3b6-61001317620f', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 20, 20, 'The number of undecayed nuclei in a sample is doubled. What happens to the activity?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'A = λN, so with λ fixed the activity is proportional to N. Mark scheme (1 mark). B1: D (It doubles).', 1, NULL, NULL),
('ca29db65-b4a0-5158-ae0f-b3c1a51f5e3d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 21, 21, 'A source of activity 2000 Bq gives a corrected count rate of 50 s⁻¹. What percentage of the decays are counted?', NULL, 1, 'numeric'::answer_type, '2.5', '%', false, NULL, false, NULL, 'Percentage = 50 ÷ 2000 × 100 = 2.5 %. Mark scheme (2 marks). C1: count rate ÷ activity. A1: percentage = 2.5%.', 2, NULL, NULL),
('a6cfab2c-3985-5cfa-8ee6-233c5b2db125', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 22, 22, 'Which change alters the rate at which a radioactive sample decays?', NULL, 1, 'multiple_choice'::answer_type, 'None of these: heating, compressing or chemically combining the sample', NULL, false, NULL, false, NULL, 'Nuclear decay is unaffected by physical or chemical conditions. Mark scheme (1 mark). B1: B (None of these: heating, compressing or chemically combining the sample).', 1, NULL, NULL),
('d4a16f7c-3582-5bb8-85d1-0885a8902582', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 23, 23, 'A sample contains 1.0 × 10⁶ nuclei with decay constant 3.0 × 10⁻⁴ s⁻¹. How many are expected to decay in the next second?', NULL, 1, 'numeric'::answer_type, '300', NULL, false, NULL, false, NULL, 'Expected decays = λN = 3.0 × 10⁻⁴ × 1.0 × 10⁶ = 300. Mark scheme (1 mark). A1: decays = 300.', 1, NULL, NULL),
('bda439d6-efd9-5a0c-a358-5cfddea6c91c', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 24, 24, 'A source contains 4.0 × 10¹² nuclei and has an activity of 1.0 × 10⁸ Bq. What is the probability that a given nucleus decays in the next second?', NULL, 1, 'numeric'::answer_type, '2.5e-5', NULL, false, NULL, false, NULL, 'Probability per second = λ = A/N = 1.0 × 10⁸ ÷ 4.0 × 10¹² = 2.5 × 10⁻⁵. Mark scheme (2 marks). C1: λ = A/N. A1: probability = 2.5 × 10⁻⁵.', 2, NULL, NULL),
('275eef12-b992-5f62-b22f-dc5dfcae0d48', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 25, 25, 'A sample contains 1.0 µg of radium-226 (molar mass 0.226 kg mol⁻¹), whose decay constant is 1.37 × 10⁻¹¹ s⁻¹. Calculate its activity. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '36493', 'Bq', false, NULL, false, NULL, 'N = 1.0 × 10⁻⁹ ÷ 0.226 × 6.02 × 10²³ = 2.664 × 10¹⁵. A = 1.37 × 10⁻¹¹ × 2.664 × 10¹⁵ = 3.65 × 10⁴ Bq. Mark scheme (3 marks). C1: N from mass. C1: A = λN. A1: A = 3.65 × 10⁴ Bq.', 3, NULL, NULL),
('3ae22a69-bd41-5e03-8233-45681fd74f59', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 26, 26, 'A radium-226 source (molar mass 0.226 kg mol⁻¹, decay constant 1.37 × 10⁻¹¹ s⁻¹) has an activity of 3.7 × 10¹⁰ Bq. Calculate the mass of radium in mg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1014 mg', 'mg', false, NULL, false, NULL, 'N = A/λ = 3.7 × 10¹⁰ ÷ 1.37 × 10⁻¹¹ = 2.701 × 10²¹. m = 2.701 × 10²¹ ÷ 6.02 × 10²³ × 0.226 = 0.001014 kg. In mg: 0.001014 × 10⁶ = 1010. Mark scheme (4 marks). C1: N = A/λ. C1: moles × molar mass. C1: kg to mg. A1: m = 1010 mg.', 4, NULL, NULL),
('13544a4f-5beb-5a33-8f5d-48ca40573271', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 27, 27, 'A count of N is taken from a random source. Roughly how large is the random uncertainty in it?', NULL, 2, 'multiple_choice'::answer_type, '√N', NULL, false, NULL, false, NULL, 'Random counts scatter by about √N, so larger counts are relatively more precise. Mark scheme (3 marks). C1: Poisson spread. C1: √N. A1: C (√N).', 3, NULL, NULL),
('8a68e0b9-95c1-5dfe-94df-f6abe38138cd', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 28, 28, 'A count of 400 is recorded in a fixed time. Estimate the percentage uncertainty in the count, taking the uncertainty as √N.', NULL, 2, 'numeric'::answer_type, '5', '%', false, NULL, false, NULL, '√400 = 20. Percentage = 20 ÷ 400 × 100 = 5.0 %. Mark scheme (3 marks). C1: √N. C1: percentage. A1: uncertainty = 5.0%.', 3, NULL, NULL),
('34ac69bc-2c89-5c12-87b0-3c30273cacb7', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 29, 29, 'How many counts must be recorded for the random uncertainty, taken as √N, to be 2.0% of the count?', NULL, 2, 'numeric'::answer_type, '2500', NULL, false, NULL, false, NULL, '√N/N = 1/√N = 0.020, so N = (1 ÷ 0.020)² = 2500. Mark scheme (4 marks). M1: √N ÷ N = 1/√N. C1: equation. C1: value. A1: N = 2500.', 4, NULL, NULL),
('8d61dde2-c5e5-58bb-b61b-47a97876c186', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 30, 30, 'In a class model, many dice are thrown and every die showing a six is removed. What does this model?', NULL, 2, 'multiple_choice'::answer_type, 'Random decay with a fixed probability (1/6) per throw for each die', NULL, false, NULL, false, NULL, 'Each die has the same chance each throw, like λ for a nucleus. Mark scheme (3 marks). C1: fixed probability. C1: number removed ∝ number left. A1: A (Random decay with a fixed probability (1/6) per throw for each die).', 3, NULL, NULL),
('3e7cdca8-13e2-5b6d-9a0a-9ef362533d7b', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 31, 31, 'In the dice model, 600 dice are thrown and the sixes removed, then the rest are thrown again. Predict the number left after two throws.', NULL, 2, 'numeric'::answer_type, '416.7', NULL, false, NULL, false, NULL, 'Each throw leaves 5/6: N = 600 × (5 ÷ 6)² = 417. Mark scheme (3 marks). C1: factor 5/6 each throw. C1: two throws. A1: N = 417.', 3, NULL, NULL),
('f3217ea8-3329-571c-a535-95f18a71171d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 32, 32, 'A source has an activity of 5000 Bq, and 1.2% of its emissions are counted by a detector. Calculate the count rate due to the source in counts s⁻¹.', NULL, 2, 'numeric'::answer_type, '60', 'counts s⁻¹', false, NULL, false, NULL, 'Count rate = 0.012 × 5000 = 60 counts s⁻¹. Mark scheme (3 marks). C1: fraction counted. C1: × activity. A1: count rate = 60 counts s⁻¹.', 3, NULL, NULL),
('5c146c18-a9a7-59d4-8a6c-5a860b466574', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 33, 33, 'Why does counting for a longer time give a more reliable count rate from a radioactive source?', NULL, 2, 'multiple_choice'::answer_type, 'The relative random uncertainty √N/N gets smaller as the count N increases', NULL, false, NULL, false, NULL, 'Bigger counts reduce the fractional scatter. Mark scheme (3 marks). C1: √N/N = 1/√N. C1: falls as N grows. A1: D (The relative random uncertainty √N/N gets smaller as the count N increases).', 3, NULL, NULL),
('c1097d43-ae26-5d8e-a0f9-8ddb3804fb61', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 34, 34, 'On average, 1 in 5000 nuclei of an isotope decays each second. Calculate its decay constant.', NULL, 2, 'numeric'::answer_type, '2e-4', 's⁻¹', false, NULL, false, NULL, 'λ = probability per second = 1 ÷ 5000 = 2.0 × 10⁻⁴ s⁻¹. Mark scheme (3 marks). C1: λ as a probability. C1: value. A1: λ = 2.0 × 10⁻⁴ s⁻¹.', 3, NULL, NULL),
('6c590d53-f250-5e29-ac2e-de4f7160fcac', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 35, 35, 'A detector records 1200 counts in 5.0 minutes near a source. The background rate is 0.40 counts s⁻¹. Calculate the corrected count rate due to the source in counts s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.6', 'counts s⁻¹', false, NULL, false, NULL, 'Total rate = 1200 ÷ 300 = 4.0 counts s⁻¹. Corrected = 4.0 − 0.40 = 3.6 counts s⁻¹. Mark scheme (4 marks). C1: minutes to seconds. C1: total rate. C1: subtract background. A1: count rate = 3.6 counts s⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fge019b5c0-t fge019b5c0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge019b5c0-t">Counting a source</title><desc id="fge019b5c0-d">A radioactive source in a holder in front of the window of a GM tube, which is connected to a counter.</desc><rect x="30" y="60" width="14" height="60" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="44" y="82" width="16" height="16" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="52" y="136" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">source</text><rect x="200" y="74" width="110" height="32" rx="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="200" y1="74" x2="200" y2="106" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="255" y="124" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">GM tube</text><line x1="310" y1="90" x2="330" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M330,90 C350,90 350,140 370,140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="370" y="120" width="40" height="40" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="390" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">counter</text></svg>', 'A radioactive source in a holder in front of the window of a GM tube, which is connected to a counter.'),
('29df142e-2f16-57c1-8c3b-627c84d26003', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 36, 36, 'Two sources have the same activity. Source X has a smaller decay constant than source Y. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'X contains more undecayed nuclei', NULL, false, NULL, false, NULL, 'N = A/λ: for equal A, smaller λ means larger N. Mark scheme (3 marks). C1: N = A/λ. C1: inverse. A1: B (X contains more undecayed nuclei).', 3, NULL, NULL),
('878913ab-8a8d-5c5b-a48a-74930046fd31', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 37, 37, 'One mole of a nuclide has a decay constant of 1.0 × 10⁻¹⁰ s⁻¹. Calculate its activity. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '6.02e13', 'Bq', false, NULL, false, NULL, 'A = λN = 1.0 × 10⁻¹⁰ × 6.02 × 10²³ = 6.02 × 10¹³ Bq. Mark scheme (3 marks). C1: N = N_A. C1: A = λN. A1: A = 6.02 × 10¹³ Bq.', 3, NULL, NULL),
('a5033265-d2b9-54d2-b04a-1cb4372207bb', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 38, 38, 'An iodine-131 source in a hospital has an activity of 8.0 × 10⁵ Bq and a decay constant of 1.0 × 10⁻⁶ s⁻¹. How many iodine-131 nuclei does it contain?', NULL, 2, 'numeric'::answer_type, '8e11', NULL, false, NULL, false, NULL, 'N = A/λ = 8.0 × 10⁵ ÷ 1.0 × 10⁻⁶ = 8.0 × 10¹¹. Mark scheme (3 marks). C1: N = A/λ. C1: value. A1: N = 8.0 × 10¹¹.', 3, NULL, NULL),
('cd650b5c-f77f-5a9e-a853-19c04eece076', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 39, 39, 'Which are major sources of background radiation in most places?', NULL, 2, 'multiple_choice'::answer_type, 'Radon gas, rocks and soil, and cosmic rays', NULL, false, NULL, false, NULL, 'Natural sources dominate the background count. Mark scheme (3 marks). C1: natural sources. C1: radon a major part. A1: C (Radon gas, rocks and soil, and cosmic rays).', 3, NULL, NULL),
('b6b7968b-cfe1-529a-a423-fd24801e1970', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 40, 40, 'A source has a steady activity of 2.0 × 10⁴ Bq. How many decays happen in one hour?', NULL, 2, 'numeric'::answer_type, '7.2e7', NULL, false, NULL, false, NULL, 'Decays = 2.0 × 10⁴ × 3600 = 7.2 × 10⁷. Mark scheme (3 marks). C1: hour to seconds. C1: decays = A × t. A1: decays = 7.2 × 10⁷.', 3, NULL, NULL),
('2fff37cc-6846-5ada-b9f7-506836e6a3f6', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 41, 41, 'For a sample of N nuclei, how many are expected to decay in a short time Δt?', NULL, 2, 'multiple_choice'::answer_type, 'λNΔt', NULL, false, NULL, false, NULL, 'Each nucleus has probability λΔt of decaying. Mark scheme (3 marks). C1: probability λΔt each. C1: × N. A1: A (λNΔt).', 3, NULL, NULL),
('a15460ef-c1a2-568e-a51d-8fd7799dd843', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 42, 42, 'A GM tube records 2.4 × 10³ counts in 1.0 minute from a source whose activity is 1.0 × 10⁵ Bq. What percentage of the decays does it record? (Ignore background.)', NULL, 2, 'numeric'::answer_type, '0.04', '%', false, NULL, false, NULL, 'Count rate = 2.4 × 10³ ÷ 60 = 40 s⁻¹. Percentage = 40 ÷ 1.0 × 10⁵ × 100 = 0.040 %. Mark scheme (3 marks). C1: counts per second. C1: ratio × 100. A1: percentage = 0.040%.', 3, NULL, NULL),
('99ddfbae-30b1-53b8-a884-737fd6189c88', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 43, 43, 'Two equal samples of the same isotope are kept at 20 °C and at 800 °C. How do their activities compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are the same, because nuclear decay does not depend on temperature', NULL, false, NULL, false, NULL, 'Nuclear processes are unaffected by the thermal energy of atoms. Mark scheme (3 marks). C1: decay spontaneous. C1: same λ, same N. A1: D (They are the same, because nuclear decay does not depend on temperature).', 3, NULL, NULL),
('be382197-149a-5fa1-a5e5-2d24b8c14d7a', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 44, 44, 'A source of activity 6.0 × 10⁴ Bq contains 1.5 × 10¹² undecayed nuclei. Calculate 1/λ, the mean lifetime of a nucleus of this isotope, in seconds.', NULL, 2, 'numeric'::answer_type, '2.5e7', 's', false, NULL, false, NULL, 'λ = A/N = 6.0 × 10⁴ ÷ 1.5 × 10¹² = 4.0 × 10⁻⁸ s⁻¹. 1/λ = 1.5 × 10¹² ÷ 6.0 × 10⁴ = 2.5 × 10⁷ s. Mark scheme (3 marks). C1: λ = A/N. C1: 1/λ. A1: 1/λ = 2.5 × 10⁷ s.', 3, NULL, NULL),
('fe324d6d-c10e-5697-8ea4-fabf922a1d23', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 45, 45, 'A cobalt-60 source contains 1.0 mg of cobalt-60 (molar mass 0.060 kg mol⁻¹), whose decay constant is 4.17 × 10⁻⁹ s⁻¹. (a) Calculate the number of moles. (b) Calculate the number of nuclei. (c) Calculate the activity. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '4.184e10', 'Bq', false, NULL, false, NULL, '(a) n = 1.0 × 10⁻⁶ ÷ 0.060 = 1.667 × 10⁻⁵ mol. (b) N = 1.667 × 10⁻⁵ × 6.02 × 10²³ = 1.003 × 10¹⁹. (c) A = 4.17 × 10⁻⁹ × 1.003 × 10¹⁹ = 4.18 × 10¹⁰ Bq. Mark scheme (5 marks). C1: mg to kg. C1: moles. C1: nuclei. C1: A = λN. A1: A = 4.18 × 10¹⁰ Bq.', 5, NULL, NULL),
('43943228-f41d-5c00-af4b-fb5e5c6af5ff', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 46, 46, 'A smoke detector contains 0.30 µg of americium-241 (molar mass 0.241 kg mol⁻¹, decay constant 5.08 × 10⁻¹¹ s⁻¹). (a) Calculate the number of nuclei. (b) Calculate the activity. (c) Explain why the activity hardly changes during the life of the detector. Give only the answer to (b). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '38068', 'Bq', false, NULL, false, NULL, '(a) N = 0.30 × 10⁻⁹ ÷ 0.241 × 6.02 × 10²³ = 7.494 × 10¹⁴. (b) A = 5.08 × 10⁻¹¹ × 7.494 × 10¹⁴ = 3.81 × 10⁴ Bq. (c) λ is tiny, so only a minute fraction decays in ten years. Mark scheme (6 marks). C1: µg to kg. C1: number of nuclei. M1: A = λN. C1: value. B1: small λ, long half-life. A1: A = 3.81 × 10⁴ Bq.', 6, NULL, NULL),
('e8ba4314-d3c1-545b-9e17-697368a73cb2', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 47, 47, 'A detector records 900 counts in 3.0 minutes from a source. The background is 25 counts per minute. (a) Calculate the count rate. (b) Calculate the corrected count rate in counts per minute. (c) Estimate the percentage uncertainty in the 900 counts.', NULL, 3, 'numeric'::answer_type, '275', 'counts per minute', false, NULL, false, NULL, '(a) 900 ÷ 3.0 = 300 counts per minute. (b) 300 − 25 = 275 counts per minute. (c) √900 = 30, which is 3.3 %. Mark scheme (5 marks). C1: rate. M1: subtract background. C1: value. B1: √N uncertainty. A1: count rate = 275 counts per minute.', 5, NULL, NULL),
('a4296670-2a6a-515f-8ebb-2495237d909e', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 48, 48, 'In a sample of 2.0 × 10⁹ nuclei, 3.0 × 10⁴ decay in 10 s. Assume the number of nuclei hardly changes in this time. (a) Calculate the activity. (b) Calculate the decay constant.', NULL, 3, 'numeric'::answer_type, '1.5e-6', 's⁻¹', false, NULL, false, NULL, '(a) A = 3.0 × 10⁴ ÷ 10 = 3000 Bq. (b) λ = A/N = 3000 ÷ 2.0 × 10⁹ = 1.5 × 10⁻⁶ s⁻¹. Mark scheme (5 marks). C1: decays per second. M1: λ = A/N. C1: value. B1: N almost constant. A1: λ = 1.5 × 10⁻⁶ s⁻¹.', 5, NULL, NULL),
('bc259ece-e2a2-545f-b9ac-e03fea447429', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 49, 49, 'A class throws 1200 dice repeatedly, removing the sixes each time. (a) Predict the number left after 5 throws. (b) Show that the "half-life" n in throws satisfies (5/6)ⁿ = 0.5. (c) Calculate n.', NULL, 3, 'numeric'::answer_type, '3.802', NULL, false, NULL, false, NULL, '(a) 1200 × (5/6)⁵ = 482. (b) Half remain when (5/6)ⁿ = 1/2. (c) n = ln 2 ÷ ln(6 ÷ 5) = 3.80. Mark scheme (6 marks). C1: number left. B1: half-life condition. M1: take logs. C1: rearranged. C1: value. A1: n = 3.80.', 6, NULL, NULL),
('897c289d-4f43-52b1-98ed-c508fbe46d14', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 50, 50, 'Air in a room of volume 50 m³ contains radon with an activity of 100 Bq per m³. The decay constant of radon-222 is 2.1 × 10⁻⁶ s⁻¹. (a) Calculate the total radon activity. (b) Calculate the number of radon nuclei in the room.', NULL, 3, 'numeric'::answer_type, '2.381e9', NULL, false, NULL, false, NULL, '(a) A = 100 × 50 = 5000 Bq. (b) N = A/λ = 5000 ÷ 2.1 × 10⁻⁶ = 2.38 × 10⁹. Mark scheme (5 marks). C1: total activity. M1: N = A/λ. C1: substitution. C1: value. A1: N = 2.38 × 10⁹.', 5, NULL, NULL),
('7e0ad9bf-5361-51f4-99cf-b46e298b966c', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 51, 51, 'A patient is given technetium-99m with an activity of 400 MBq. Its decay constant is 3.2 × 10⁻⁵ s⁻¹ and its molar mass is 0.099 kg mol⁻¹. (a) Calculate the number of technetium nuclei. (b) Calculate their mass. Give only the answer to (b), in units of 10⁻¹² kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '2.056', '10⁻¹² kg', false, NULL, false, NULL, '(a) N = 400 × 10⁶ ÷ 3.2 × 10⁻⁵ = 1.250 × 10¹³. (b) m = 1.250 × 10¹³ ÷ 6.02 × 10²³ × 0.099 = 2.06 × 10⁻¹² kg. Mark scheme (6 marks). C1: MBq to Bq. C1: N = A/λ. M1: mass = (N/N_A) × M. C1: substitution. C1: value. A1: m = 2.06 × 10⁻¹² kg.', 6, NULL, NULL),
('cda9ea34-c4d9-5a1e-a7c3-ea9983a6f845', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 52, 52, 'A γ-source gives a corrected count rate of 120 counts s⁻¹ at 10 cm from a detector. Assuming an inverse-square law and no absorption, (a) state how the rate depends on distance, and (b) calculate the corrected count rate at 20 cm.', NULL, 3, 'numeric'::answer_type, '30', 'counts s⁻¹', false, NULL, false, NULL, '(a) Rate ∝ 1/d². (b) 120 × (10 ÷ 20)² = 30 counts s⁻¹. Mark scheme (5 marks). B1: inverse square. M1: ratio of squares. C1: substitution. C1: value. A1: count rate = 30 counts s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg770a47da-t fg770a47da-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg770a47da-t">Source and detector</title><desc id="fg770a47da-d">A γ-source facing the window of a GM tube connected to a counter, first 10 cm from the detector and then 20 cm.</desc><rect x="30" y="60" width="14" height="60" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="44" y="82" width="16" height="16" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="52" y="136" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">source</text><rect x="200" y="74" width="110" height="32" rx="6" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="200" y1="74" x2="200" y2="106" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="255" y="124" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">GM tube</text><line x1="310" y1="90" x2="330" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M330,90 C350,90 350,140 370,140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="370" y="120" width="40" height="40" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="390" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">counter</text><polygon points="60,46 66.3,43 66.3,49" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="64.9" y1="46" x2="195.1" y2="46" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,46 193.7,49 193.7,43" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="130" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 cm, then 20 cm</text></svg>', 'A γ-source facing the window of a GM tube connected to a counter, first 10 cm from the detector and then 20 cm.'),
('934c845f-326f-59f2-802e-e02d6fee5148', 'aae53119-5afd-4055-b81b-60e6244772d7', '7e92910a-485e-4872-a909-b370e88e8ace', 'a-level', '29.5', '9702 coursebook 29.5 · Randomness and radioactive decay', 53, 53, 'Equal masses of strontium-90 (molar mass 0.090 kg mol⁻¹, λ = 7.6 × 10⁻¹⁰ s⁻¹) and caesium-137 (molar mass 0.137 kg mol⁻¹, λ = 7.3 × 10⁻¹⁰ s⁻¹) are compared. (a) Show that the number of nuclei is inversely proportional to the molar mass. (b) Calculate (activity of strontium) ÷ (activity of caesium).', NULL, 3, 'numeric'::answer_type, '1.585', NULL, false, NULL, false, NULL, '(a) N = (m/M)N_A, so N ∝ 1/M for equal m. (b) A ∝ λ/M: ratio = (7.6 × 10⁻¹⁰ ÷ 0.090) ÷ (7.3 × 10⁻¹⁰ ÷ 0.137) = 1.58. Mark scheme (6 marks). B1: N ∝ 1/M. M1: A = λN. C1: ratio expression. C1: substitution. C1: value. A1: ratio = 1.58.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('db9da3af-5e32-55ae-b2c8-51023894c541', '43116c33-7c2f-527e-8e86-2f77bbf3c6cc', 'It happens only when the nucleus is struck', 'A', false, 0),
('10876f81-c6d2-5b8a-9eab-0f8a1a6ca3ee', '43116c33-7c2f-527e-8e86-2f77bbf3c6cc', 'Every nucleus decays at the same moment', 'B', false, 1),
('d8faa62f-8a00-5e56-ab7f-1d6c60555c93', '43116c33-7c2f-527e-8e86-2f77bbf3c6cc', 'It is not affected by external conditions such as temperature or pressure', 'C', true, 2),
('c3b02da4-54f0-5e9d-ba45-91d4db131977', '43116c33-7c2f-527e-8e86-2f77bbf3c6cc', 'It can be speeded up by heating', 'D', false, 3),
('61186001-ef50-55ee-8821-1bf38a51edca', '6a2fbab7-ee9a-5d2b-80e0-14275531112c', 'One decay per second', 'A', true, 0),
('0ed538de-d17c-5aa5-ab83-39d6aadac739', '6a2fbab7-ee9a-5d2b-80e0-14275531112c', 'One count per minute', 'B', false, 1),
('de62b707-a5bd-5c3a-8294-d6367a400275', '6a2fbab7-ee9a-5d2b-80e0-14275531112c', 'The activity of 1 g of radium', 'C', false, 2),
('802ed8d1-70c0-579e-ac18-1d6c2191ae87', '6a2fbab7-ee9a-5d2b-80e0-14275531112c', 'One nucleus remaining', 'D', false, 3),
('a568e6cd-e290-5896-9bc8-e86f91310ac7', 'ce9596cb-a300-5938-b71a-bf49dcea0e65', 'The time for half the nuclei to decay', 'A', false, 0),
('449ac58c-be45-5c77-921b-209611b40351', 'ce9596cb-a300-5938-b71a-bf49dcea0e65', 'The number of nuclei decaying each second', 'B', false, 1),
('e8168c87-584a-5b45-a353-afd8d9ff5b23', 'ce9596cb-a300-5938-b71a-bf49dcea0e65', 'The energy released per decay', 'C', false, 2),
('5edeb091-d74b-5702-86e0-bcb2221c4722', 'ce9596cb-a300-5938-b71a-bf49dcea0e65', 'The probability per unit time that any one nucleus decays', 'D', true, 3),
('94acc67c-59b4-5ffe-aa49-3bb4f4c36378', '6c032029-8c42-58fe-84ac-43ec1a5fbc9f', 'Nuclei decay in a fixed order', 'A', false, 0),
('2205081d-e15a-55ce-83e8-342c4f8778cb', '6c032029-8c42-58fe-84ac-43ec1a5fbc9f', 'It is impossible to predict which nucleus will decay next or when', 'B', true, 1),
('154b92a7-0540-5fea-8ccc-c64cfed4484c', '6c032029-8c42-58fe-84ac-43ec1a5fbc9f', 'Every nucleus decays after the same time', 'C', false, 2),
('cfd7cff2-32a2-546d-8ac1-6df87e6503bb', '6c032029-8c42-58fe-84ac-43ec1a5fbc9f', 'Decay happens only when a nucleus is disturbed', 'D', false, 3),
('68eb7d81-9a87-5b33-acd6-7eeea789bea4', '829c9250-5276-557f-80a6-96b3206a5917', 'The detector is faulty', 'A', false, 0),
('1ce2cc98-e874-511f-932d-a76d061cab1a', '829c9250-5276-557f-80a6-96b3206a5917', 'The source is losing activity quickly', 'B', false, 1),
('9ee97982-0e8b-52d1-9ea1-8bcfe9a90d0e', '829c9250-5276-557f-80a6-96b3206a5917', 'Radioactive decay is random', 'C', true, 2),
('279e3682-b746-53fc-b5e5-2a0fb085b30e', '829c9250-5276-557f-80a6-96b3206a5917', 'The background is zero', 'D', false, 3),
('96629e4f-e30a-53aa-984d-52b30281e4c5', 'ddf328a1-ef4c-5c9a-819c-cad3987d7238', 'Radiation goes off in all directions and not all of it entering the detector is detected', 'A', true, 0),
('792f7fe7-93c1-5c14-9371-534ee8672463', 'ddf328a1-ef4c-5c9a-819c-cad3987d7238', 'Some nuclei decay without emitting anything', 'B', false, 1),
('088194e1-bfd2-53be-b77c-b8a647732001', 'ddf328a1-ef4c-5c9a-819c-cad3987d7238', 'The source decays more slowly near a detector', 'C', false, 2),
('5f607867-12b9-5cef-a8c3-3e5df1de88f7', 'ddf328a1-ef4c-5c9a-819c-cad3987d7238', 'The background reduces the count', 'D', false, 3),
('d76f5c12-4029-53e1-8c1c-3769dd39e340', '1880bbe8-64fb-51f6-b3b6-61001317620f', 'It halves', 'A', false, 0),
('276c6bc4-f4ab-5a56-b0db-d769d38138eb', '1880bbe8-64fb-51f6-b3b6-61001317620f', 'It is unchanged', 'B', false, 1),
('ae6ce708-4b2e-516c-92c1-a75f5ac57eba', '1880bbe8-64fb-51f6-b3b6-61001317620f', 'It quadruples', 'C', false, 2),
('300086bd-9243-5b7f-8991-7587e25850f7', '1880bbe8-64fb-51f6-b3b6-61001317620f', 'It doubles', 'D', true, 3),
