('89c1a91b-3025-5725-88e1-8a2d1287a405', '8d61dde2-c5e5-58bb-b61b-47a97876c186', 'A constant number decaying per throw', 'D', false, 3),
('620e9f40-0319-5ec9-a061-1c485ab154c4', '5c146c18-a9a7-59d4-8a6c-5a860b466574', 'The source becomes more active', 'A', false, 0),
('95bba2df-dd9f-5f9e-8651-11a0887d621f', '5c146c18-a9a7-59d4-8a6c-5a860b466574', 'The background falls with time', 'B', false, 1),
