('1075bdfa-30eb-51f3-9e18-4c30f5c1ffd4', '5c146c18-a9a7-59d4-8a6c-5a860b466574', 'The relative random uncertainty √N/N gets smaller as the count N increases', 'D', true, 3),
('3a262bc6-6eff-5a74-876a-33f521cbbb8f', '29df142e-2f16-57c1-8c3b-627c84d26003', 'Y contains more undecayed nuclei', 'A', false, 0),
('ab7f5247-fb2a-5669-8ef2-13120becfaab', '29df142e-2f16-57c1-8c3b-627c84d26003', 'X contains more undecayed nuclei', 'B', true, 1),
('6322a972-84e6-5890-b149-a06bd8ada634', '29df142e-2f16-57c1-8c3b-627c84d26003', 'They contain the same number of nuclei', 'C', false, 2),
('a148c530-cfbc-57a9-9792-c254d8ef10a3', '29df142e-2f16-57c1-8c3b-627c84d26003', 'X has the shorter half-life', 'D', false, 3),
('167a7613-df42-581c-bb53-18824554a077', 'cd650b5c-f77f-5a9e-a853-19c04eece076', 'Mobile phones and radio masts', 'A', false, 0),
