INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('aa65980e-d8e2-5dad-ba58-c5d1db3d7e3b', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 7, 7, 'What fraction of a radioactive sample remains undecayed after six half-lives?', NULL, 1, 'numeric'::answer_type, '0.01562', NULL, false, NULL, false, NULL, 'Fraction = (1/2)⁶ = 0.5^6 = 0.0156. Mark scheme (2 marks). C1: (1/2)ⁿ. A1: fraction = 0.0156.', 2, NULL, NULL),
('f8831859-dc91-517f-b82d-be30b1ee097e', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 8, 8, 'In N = N₀e^(−λt), what does N₀ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The number of undecayed nuclei at t = 0', NULL, false, NULL, false, NULL, 'N₀ is the starting number of undecayed nuclei. Mark scheme (1 mark). B1: C (The number of undecayed nuclei at t = 0).', 1, NULL, NULL),
('192f8fd9-f2d7-5a78-8b54-c7d2f3c9df85', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 9, 9, 'The decay constant of an isotope in a laboratory test source is 0.0030 s⁻¹. How long does it take for half of its nuclei to decay?', NULL, 1, 'numeric'::answer_type, '231', 's', false, NULL, false, NULL, 't½ = ln 2 ÷ λ = 0.693 ÷ 0.0030 = 231 s. Mark scheme (2 marks). C1: t½ = ln 2/λ. A1: t½ = 231 s.', 2, NULL, NULL),
('b093dd44-4b74-5727-a990-67bb55f84e17', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 10, 10, 'What is the half-life of a radioactive isotope?', NULL, 1, 'multiple_choice'::answer_type, 'The mean time for half the undecayed nuclei in a sample to decay', NULL, false, NULL, false, NULL, 'After each half-life N and A halve. Mark scheme (1 mark). B1: A (The mean time for half the undecayed nuclei in a sample to decay).', 1, NULL, NULL),
('71cc05b4-c82f-560a-9f63-fe07f12e6c31', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 11, 11, 'Iodine-131 has a half-life of 8.0 days. Calculate its decay constant in s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.003e-6', 's⁻¹', false, NULL, false, NULL, 't½ = 8.0 × 86400 = 6.912 × 10⁵ s. λ = 0.693 ÷ 6.912 × 10⁵ = 1.00 × 10⁻⁶ s⁻¹. Mark scheme (2 marks). C1: days to s, then λ = ln 2/t½. A1: λ = 1.00 × 10⁻⁶ s⁻¹.', 2, NULL, NULL),
('04d0ccb4-a8f5-56ad-a898-b81ab8c161fc', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 12, 12, 'A source has an activity of 640 Bq. What will its activity be after one half-life?', NULL, 1, 'multiple_choice'::answer_type, '320 Bq', NULL, false, NULL, false, NULL, 'Activity halves in each half-life. Mark scheme (1 mark). B1: D (320 Bq).', 1, NULL, NULL),
('ba0d64cc-97b2-5612-a280-d663f139c00a', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 13, 13, 'A sample starts with 8.0 × 10¹² undecayed nuclei. How many remain after three half-lives?', NULL, 1, 'numeric'::answer_type, '1e12', NULL, false, NULL, false, NULL, 'N = 8.0 × 10¹² × (1/2)³ = 1.0 × 10¹². Mark scheme (2 marks). C1: halve three times. A1: N = 1.0 × 10¹².', 2, NULL, NULL),
('c05ebac0-3607-535c-9b09-ee94ec6d861c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 14, 14, 'Which equation links the decay constant λ and the half-life t½?', NULL, 1, 'multiple_choice'::answer_type, 'λt½ = ln 2', NULL, false, NULL, false, NULL, 'Setting N = N₀/2 in N = N₀e^(−λt) gives λt½ = ln 2. Mark scheme (1 mark). B1: B (λt½ = ln 2).', 1, NULL, NULL),
('0e67f665-5957-5bc5-b2a8-31b3a6868a76', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 15, 15, 'For an isotope with λ = 0.050 s⁻¹, calculate the fraction of nuclei remaining after 20 s.', NULL, 1, 'numeric'::answer_type, '0.3679', NULL, false, NULL, false, NULL, 'N/N₀ = e^(−λt) = e^(−0.050 × 20) = 0.368. Mark scheme (2 marks). C1: N/N₀ = e^(−λt). A1: fraction = 0.368.', 2, NULL, NULL),
('3afeaa32-f2e9-5fed-924a-db57769002a0', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 16, 16, 'What is the shape of a graph of the number of undecayed nuclei against time?', NULL, 1, 'multiple_choice'::answer_type, 'An exponential decay curve', NULL, false, NULL, false, NULL, 'Equal fractions decay in equal times. Mark scheme (1 mark). B1: C (An exponential decay curve).', 1, NULL, NULL),
('45b95d86-b3f8-5018-a7d8-934895ca4b43', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 17, 17, 'A source of half-life 6.0 h has an activity of 1600 Bq. Calculate its activity 24 h later.', NULL, 1, 'numeric'::answer_type, '100', 'Bq', false, NULL, false, NULL, 'Four half-lives: A = 1600 × (1/2)⁴ = 100 Bq. Mark scheme (2 marks). C1: number of half-lives. A1: A = 100 Bq.', 2, NULL, NULL),
('627e5078-b957-5407-a75e-848f4b6f965e', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 18, 18, 'Which is a correct unit for the decay constant?', NULL, 1, 'multiple_choice'::answer_type, 's⁻¹', NULL, false, NULL, false, NULL, 'λ is a probability per unit time. Mark scheme (1 mark). B1: A (s⁻¹).', 1, NULL, NULL),
('760c89e6-9c49-5608-aff9-eb2123e25f11', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 19, 19, 'Cobalt-60 has a half-life of 5.3 years. How many years do three half-lives take?', NULL, 1, 'numeric'::answer_type, '15.9', 'years', false, NULL, false, NULL, 't = 3 × 5.3 = 15.9 years. Mark scheme (2 marks). C1: 3 × t½. A1: t = 15.9 years.', 2, NULL, NULL),
('ada026bb-dc89-50d6-b88e-ea2e0a041c34', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 20, 20, 'A sample contains 1000 radioactive nuclei. After one half-life, how many remain undecayed?', NULL, 1, 'multiple_choice'::answer_type, 'About 500, but not exactly, because decay is random', NULL, false, NULL, false, NULL, 'Half-life describes the average behaviour of large samples. Mark scheme (1 mark). B1: D (About 500, but not exactly, because decay is random).', 1, NULL, NULL),
('6a7b6d25-bcc1-59fe-acc2-127fc8f5afcc', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 21, 21, 'What percentage of a sample has decayed after two half-lives?', NULL, 1, 'numeric'::answer_type, '75', '%', false, NULL, false, NULL, 'Remaining = 1/4, so decayed = (1 − 0.25) × 100 = 75 %. Mark scheme (2 marks). C1: 1 − (1/2)². A1: decayed = 75%.', 2, NULL, NULL),
('eed343c5-03d5-5b58-a83b-e40cb9574bd4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 22, 22, 'Over what time does the activity of a source halve if its decay constant is 2.5 × 10⁻³ s⁻¹?', NULL, 1, 'numeric'::answer_type, '277.3', 's', false, NULL, false, NULL, 't½ = 0.693 ÷ 2.5 × 10⁻³ = 277 s. Mark scheme (2 marks). C1: t½ = ln 2/λ. A1: t½ = 277 s.', 2, NULL, NULL),
('914cbaae-5d5f-582d-a5da-ee3938904af1', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 23, 23, 'Starting from 1200 Bq, a source decays for a time equal to two of its half-lives. What activity remains?', NULL, 1, 'numeric'::answer_type, '300', 'Bq', false, NULL, false, NULL, 'A = 1200 × (1/2)² = 300 Bq. Mark scheme (1 mark). A1: A = 300 Bq.', 1, NULL, NULL),
('282509eb-7f5c-596f-b735-de9d98df7158', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 24, 24, 'In a sample, 2.0% of the remaining nuclei decay each second on average (λ = 0.020 s⁻¹). It begins with 5.0 × 10¹⁰ undecayed nuclei. How many are left after one minute?', NULL, 2, 'numeric'::answer_type, '1.506e10', NULL, false, NULL, false, NULL, 'N = 5.0 × 10¹⁰ × e^(−0.020 × 60) = 1.51 × 10¹⁰. Mark scheme (3 marks). C1: N = N₀e^(−λt). C1: λt = 1.2. A1: N = 1.51 × 10¹⁰.', 3, NULL, NULL),
('afc71482-7a3d-5030-bbbd-37edbc46ebdb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 25, 25, 'A medical isotope with a 4.0-hour half-life is delivered with an activity of 1000 Bq. What activity does it have 10 hours after delivery?', NULL, 2, 'numeric'::answer_type, '176.8', 'Bq', false, NULL, false, NULL, 'A = 1000 × 0.5^(10 ÷ 4.0) = 177 Bq. Mark scheme (3 marks). C1: number of half-lives = 2.5. C1: A = A₀(½)^n. A1: A = 177 Bq.', 3, NULL, NULL),
('7c5d9dae-259b-5b08-be0e-dd5ab19c0fc5', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 26, 26, 'The activity of a sample falls from 2400 Bq to 300 Bq. Its half-life is 2.5 minutes. How long does this take, in seconds?', NULL, 2, 'numeric'::answer_type, '450', 's', false, NULL, false, NULL, '2400 → 1200 → 600 → 300 is three half-lives: t = 3 × 2.5 × 60 = 450 s. Mark scheme (4 marks). M1: count halvings. C1: three half-lives. C1: minutes to seconds. A1: t = 450 s.', 4, NULL, NULL),
('651d7cd2-658d-52a8-9a63-eefe01d96f2a', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 27, 27, 'An isotope has a decay constant of 0.10 s⁻¹. How long does it take for the activity to fall to 10% of its starting value?', NULL, 2, 'numeric'::answer_type, '23.03', 's', false, NULL, false, NULL, '0.10 = e^(−0.10t), so t = ln 10 ÷ 0.10 = 23.0 s. Mark scheme (3 marks). C1: A/A₀ = e^(−λt). C1: take logs. A1: t = 23.0 s.', 3, NULL, NULL),
('00e1988d-5f33-5174-b27f-26cdaf89df3d', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 28, 28, 'Samples of isotopes P (half-life 2 min) and Q (half-life 20 min) start with the same number of nuclei. Which has the greater initial activity?', NULL, 2, 'multiple_choice'::answer_type, 'P, because it has the larger decay constant', NULL, false, NULL, false, NULL, 'A = λN and λ = ln 2/t½. Mark scheme (3 marks). C1: A = λN. C1: shorter t½ means larger λ. A1: B (P, because it has the larger decay constant).', 3, NULL, NULL),
('84f71688-66ac-5d69-b0c4-2197ce311815', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 29, 29, 'Iodine-131 has a half-life of 8.0 days. What fraction of a sample remains after 10 days?', NULL, 2, 'numeric'::answer_type, '0.4204', NULL, false, NULL, false, NULL, 'Fraction = 0.5^(10 ÷ 8.0) = 0.420. Mark scheme (3 marks). C1: n = t/t½. C1: (½)ⁿ. A1: fraction = 0.420.', 3, NULL, NULL),
('e91bd856-0f0a-5b55-be55-62bb0b9848c5', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 30, 30, 'A hospital receives iodine-131 (half-life 8.0 days) with an activity of 4.0 × 10⁸ Bq. Calculate its activity 30 days later.', NULL, 2, 'numeric'::answer_type, '2.973e7', 'Bq', false, NULL, false, NULL, 'A = 4.0 × 10⁸ × 0.5^(30 ÷ 8.0) = 2.97 × 10⁷ Bq. Mark scheme (4 marks). C1: t/t½ = 3.75. C1: (½)^3.75. C1: value. A1: A = 2.97 × 10⁷ Bq.', 4, NULL, NULL),
('966bc7dc-3598-58d1-b9b0-478ed34d377c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 31, 31, 'The activity of a sample falls from 640 Bq to 40 Bq in 20 minutes. Calculate the half-life in seconds.', NULL, 2, 'numeric'::answer_type, '300', 's', false, NULL, false, NULL, '640 → 40 is a factor of 16 = 2⁴, so four half-lives: t½ = 20 ÷ 4 × 60 = 300 s. Mark scheme (3 marks). C1: factor of 16. C1: four half-lives. A1: t½ = 300 s.', 3, NULL, NULL),
('46c59027-162f-5560-bb15-8359a95e5ce2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 32, 32, 'What fraction of the original nuclei decay during the second half-life?', NULL, 2, 'multiple_choice'::answer_type, 'One quarter', NULL, false, NULL, false, NULL, 'Half remain after one t½; half of those (¼ of the original) decay in the next. Mark scheme (3 marks). C1: ½ left after first. C1: ¼ decays in second. A1: C (One quarter).', 3, NULL, NULL),
('d9e0f9e0-4152-5a93-9901-ff99ac751498', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 33, 33, 'An isotope has a decay constant of 0.30 s⁻¹. Calculate the fraction of nuclei left after 5.0 s.', NULL, 2, 'numeric'::answer_type, '0.2231', NULL, false, NULL, false, NULL, 'N/N₀ = e^(−0.30 × 5.0) = 0.223. Mark scheme (3 marks). C1: e^(−λt). C1: λt = 1.5. A1: fraction = 0.223.', 3, NULL, NULL),
('e4a8e518-4f77-5424-b826-21531ac9ec10', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 34, 34, 'The number of undecayed nuclei in a sample falls from 6.0 × 10⁹ to 1.5 × 10⁹ in 40 s. Calculate the decay constant.', NULL, 2, 'numeric'::answer_type, '0.03466', 's⁻¹', false, NULL, false, NULL, 'A factor of 4 is two half-lives, so t½ = 20 s. λ = 0.693 ÷ 20 = 0.0347 s⁻¹. Mark scheme (3 marks). C1: two half-lives. C1: λ = ln 2/t½. A1: λ = 0.0347 s⁻¹.', 3, NULL, NULL),
('f7d194b2-e1dd-526f-abc2-3531d2a62a19', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 35, 35, 'Why can the half-life not be found by watching a single nucleus?', NULL, 2, 'multiple_choice'::answer_type, 'Decay is random: one nucleus may decay at any time; half-life is a statistical average for many nuclei', NULL, false, NULL, false, NULL, 'Half-life describes large numbers. Mark scheme (3 marks). C1: random. C1: statistical quantity. A1: A (Decay is random: one nucleus may decay at any time; half-life is a statistical average for many nuclei).', 3, NULL, NULL),
('0dff68e9-d13e-5f09-919c-0cbb2a7c6c5d', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 36, 36, 'Sodium-24 has a half-life of 15 hours. A sample contains 20 mg of it. What mass of sodium-24 remains after 60 hours, in mg?', NULL, 2, 'numeric'::answer_type, '1.25 mg', 'mg', false, NULL, false, NULL, '60 ÷ 15 = 4 half-lives: m = 20 × (1/2)⁴ = 1.25 mg. Mark scheme (4 marks). C1: number of half-lives. C1: mass halves with N. C1: value. A1: m = 1.25 mg.', 4, NULL, NULL),
('cc360394-e0a0-55ee-bac6-6b0bf97aab9f', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 37, 37, 'Wood from an ancient boat has one quarter of the carbon-14 activity per gram of living wood. Carbon-14 has a half-life of 5730 years. How old is the boat, in years?', NULL, 2, 'numeric'::answer_type, '11460', 'years', false, NULL, false, NULL, 'One quarter is two half-lives: age = 2 × 5730 = 11460 years. Mark scheme (3 marks). C1: two half-lives. C1: value. A1: age = 1.146 × 10⁴ years.', 3, NULL, NULL),
('c0d71a7b-aac4-5611-af86-0d3d1dac0061', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 38, 38, 'A sample contains 1.0 × 10⁶ nuclei with λ = 0.050 s⁻¹. How many decay in the first 10 s?', NULL, 2, 'numeric'::answer_type, '3.935e5', NULL, false, NULL, false, NULL, 'Decayed = N₀(1 − e^(−λt)) = 1.0 × 10⁶ × (1 − e^(−0.50)) = 3.93 × 10⁵. Mark scheme (3 marks). C1: N₀ − N. C1: e^(−0.50). A1: decayed = 3.93 × 10⁵.', 3, NULL, NULL),
('12f9ba5d-c363-555b-a943-165bfe2b7edb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 39, 39, 'A graph of ln N against t is drawn for a decaying sample. What is its gradient?', NULL, 2, 'multiple_choice'::answer_type, '−λ', NULL, false, NULL, false, NULL, 'Taking logs of N = N₀e^(−λt) gives ln N = ln N₀ − λt, a straight line of gradient −λ. Mark scheme (3 marks). C1: take logs. C1: gradient −λ. A1: D (−λ).', 3, NULL, NULL),
('1a0fa9fa-f656-5c96-ba76-31ea9b720aa7', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 40, 40, 'A sample contains 2.0 × 10¹² nuclei of an isotope with half-life 3.0 hours. Calculate its activity.', NULL, 2, 'numeric'::answer_type, '1.284e8', 'Bq', false, NULL, false, NULL, 'λ = 0.693 ÷ (3.0 × 3600) = 6.418 × 10⁻⁵ s⁻¹. A = 6.418 × 10⁻⁵ × 2.0 × 10¹² = 1.28 × 10⁸ Bq. Mark scheme (3 marks). C1: λ from t½ in s. C1: A = λN. A1: A = 1.28 × 10⁸ Bq.', 3, NULL, NULL),
('6fb3ef53-41f5-5b2d-96cb-430fcad32ce0', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 41, 41, 'The mass of a radioactive sample is doubled. What happens to its half-life?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'Half-life is a property of the isotope, not of the amount. Mark scheme (3 marks). C1: t½ = ln 2/λ. C1: λ independent of N. A1: B (It stays the same).', 3, NULL, NULL),
('f1b2d744-ab51-5f3c-84a3-f98491989de9', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 42, 42, 'A sample of an isotope (half-life 2.0 hours) contains 4.0 × 10¹⁴ undecayed nuclei at 08:00. (a) Calculate the decay constant. (b) Calculate the activity at 08:00. (c) Calculate the activity at 14:00.', NULL, 3, 'numeric'::answer_type, '4.814e9', 'Bq', false, NULL, false, NULL, '(a) λ = 0.693 ÷ 7200 = 9.627 × 10⁻⁵ s⁻¹. (b) A₀ = 9.627 × 10⁻⁵ × 4.0 × 10¹⁴ = 3.851 × 10¹⁰ Bq. (c) Three half-lives later: A = 3.851 × 10¹⁰ × (1/2)³ = 4.81 × 10⁹ Bq. Mark scheme (5 marks). C1: λ. C1: A = λN. M1: three half-lives. C1: value. A1: A = 4.81 × 10⁹ Bq.', 5, NULL, NULL),
('8b26a5c8-6fc8-5cd5-84c1-356d400f13e3', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 43, 43, 'A patient is injected with technetium-99m (half-life 6.0 h) of activity 500 MBq at 9 a.m. (a) Calculate the activity at 3 p.m. (b) Calculate the activity at 9 p.m. (c) Calculate the fraction of the nuclei that have decayed by 9 p.m. Give only the answer to (b), in MBq.', NULL, 3, 'numeric'::answer_type, '125', 'MBq', false, NULL, false, ARRAY['1.25e8']::text[], '(a) One half-life: 250 MBq. (b) Two half-lives: 500 × (1/2)² = 125 MBq. (c) 1 − 1/4 = 0.75. Mark scheme (6 marks). C1: 6 h = one half-life. C1: 250 MBq. M1: two half-lives. C1: value. C1: fraction decayed. A1: A = 125 MBq.', 6, NULL, NULL),
('5785727d-5d17-511a-88c7-df370fec08f2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 44, 44, 'Living wood gives 15.3 counts per minute per gram from carbon-14 (half-life 5730 years). An old sample gives 4.2 counts per minute per gram. (a) Write the equation linking the two count rates. (b) Calculate the age of the sample, in years.', NULL, 3, 'numeric'::answer_type, '10687', 'years', false, NULL, false, NULL, '(a) C = C₀e^(−λt), with C₀ = 15.3 and C = 4.2 counts per minute per gram. (b) λ = 0.693 ÷ 5730 = 1.210 × 10⁻⁴ per year; t = ln(15.3 ÷ 4.2) ÷ 1.210 × 10⁻⁴ = 1.07 × 10⁴ years. Mark scheme (5 marks). B1: exponential equation. C1: λ. M1: take logs. C1: value. A1: age = 1.07 × 10⁴ years.', 5, NULL, NULL),
('7b83ad99-e008-5d74-ae67-ab1c2bc43892', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 45, 45, 'A hospital needs a sample of an isotope (half-life 6.0 h) to have an activity of 50 MBq when it is used 18 hours after it is prepared. (a) Calculate the number of half-lives. (b) Calculate the activity needed when it is prepared. Give only the answer to (b), in MBq.', NULL, 3, 'numeric'::answer_type, '400', 'MBq', false, NULL, false, ARRAY['4e8']::text[], '(a) 18 ÷ 6.0 = 3. (b) A₀ = 50 × 2³ = 400 MBq. Mark scheme (6 marks). C1: number of half-lives. M1: work backwards. C1: × 2³. C1: value. B1: unit MBq. A1: A₀ = 400 MBq.', 6, NULL, NULL),
('3d976897-e17a-52d8-ac02-cce4d6069aeb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 46, 46, 'A plutonium-238 power source in a space probe has a half-life of 87.7 years. (a) Calculate the decay constant in year⁻¹. (b) Calculate the percentage of its initial power remaining after 20 years.', NULL, 3, 'numeric'::answer_type, '85.38', '%', false, NULL, false, NULL, '(a) λ = 0.693 ÷ 87.7 = 0.007904 year⁻¹. (b) P/P₀ = 0.5^(20 ÷ 87.7) × 100 = 85.4 %. Mark scheme (5 marks). C1: λ. M1: power ∝ activity. C1: (½)^(t/t½). C1: value. A1: percentage = 85.4%.', 5, NULL, NULL),
('8967feb3-2fdd-5dcd-ac7c-5752f4509114', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 47, 47, 'Source X has an activity of 800 Bq and half-life 2.0 min. Source Y has an activity of 200 Bq and half-life 6.0 min. (a) Write expressions for both activities. (b) Find the time at which they are equal, in s.', NULL, 3, 'numeric'::answer_type, '360', 's', false, NULL, false, NULL, '(a) A_X = 800e^(−λ_X t), A_Y = 200e^(−λ_Y t). (b) λ_X = 0.693 ÷ 2.0 = 0.3466 min⁻¹, λ_Y = 0.693 ÷ 6.0 = 0.1155 min⁻¹. Equal when 4 = e^((λ_X − λ_Y)t): t = ln 4 ÷ (0.3466 − 0.1155) = 6.000 min. In s: 6.000 × 60 = 360. Mark scheme (6 marks). B1: two exponentials. C1: both λ. M1: equate and take logs. C1: t in min. C1: in s. A1: t = 360 s.', 6, NULL, NULL),
('c34d7b17-f4c1-54d8-ac48-7b5d0ac27480', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 48, 48, 'A sample has 6.0 × 10¹⁰ undecayed nuclei at t = 0 and a decay constant of 0.020 s⁻¹. (a) Calculate the number remaining at t = 10 s. (b) Calculate the number remaining at t = 20 s. (c) Calculate the number that decay between these times.', NULL, 3, 'numeric'::answer_type, '8.905e9', NULL, false, NULL, false, NULL, '(a) 6.0 × 10¹⁰ × e^(−0.20) = 4.912 × 10¹⁰. (b) 6.0 × 10¹⁰ × e^(−0.40) = 4.022 × 10¹⁰. (c) 4.912 × 10¹⁰ − 4.022 × 10¹⁰ = 8.90 × 10⁹. Mark scheme (5 marks). C1: N at 10 s. C1: N at 20 s. M1: difference. C1: value. A1: decays = 8.90 × 10⁹.', 5, NULL, NULL),
('bcd2b258-2c76-5ac1-8f3c-49e7d5bd8d5c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 49, 49, 'A patient receives iodine-131 (half-life 8.0 days). (a) Calculate the fraction remaining after 30 days. (b) The initial activity was 3.7 × 10⁸ Bq and λ = 1.0 × 10⁻⁶ s⁻¹. Calculate the initial number of nuclei. (c) Calculate the number of nuclei that have decayed in 30 days. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.425e14', NULL, false, NULL, false, NULL, '(a) 0.5^(30 ÷ 8.0) = 0.07433. (b) N₀ = 3.7 × 10⁸ ÷ 1.0 × 10⁻⁶ = 3.7 × 10¹⁴. (c) 3.7 × 10¹⁴ × (1 − 0.07433) = 3.42 × 10¹⁴. Mark scheme (6 marks). C1: fraction left. C1: N₀ = A₀/λ. M1: fraction decayed. C1: substitution. C1: value. A1: decayed = 3.42 × 10¹⁴.', 6, NULL, NULL),
('424003a2-6305-5a41-907a-efe892406cec', 'aae53119-5afd-4055-b81b-60e6244772d7', 'f629eef1-c5f1-4ad6-a060-b766376ed3f9', 'a-level', '29.6', '9702 coursebook 29.6 · The mathematics of radioactive decay', 50, 50, 'A sample has a half-life of 12 s. (a) Show that the time for the activity to fall to one third of its initial value is t½ ln 3/ln 2. (b) Calculate this time.', NULL, 3, 'numeric'::answer_type, '19.02', 's', false, NULL, false, NULL, '(a) 1/3 = e^(−λt), so t = ln 3 ÷ λ = t½ ln 3 ÷ ln 2. (b) t = 12 × ln 3 ÷ ln 2 = 19.0 s. Mark scheme (5 marks). B1: e^(−λt) = 1/3. M1: λ = ln 2/t½. C1: substitution. C1: value. A1: t = 19.0 s.', 5, NULL, NULL)
