('a767d10a-9609-5e71-b4a9-d93fd6e68451', '627e5078-b957-5407-a75e-848f4b6f965e', 'kg s⁻¹', 'D', false, 3),
('2e099893-73cd-5242-ae9e-bbf37ce63ab7', 'ada026bb-dc89-50d6-b88e-ea2e0a041c34', 'Exactly 500', 'A', false, 0),
('ab7456ec-383f-5149-93a8-bbf285974c1d', 'ada026bb-dc89-50d6-b88e-ea2e0a041c34', 'Exactly 250', 'B', false, 1),
('384eecb3-d262-5a10-bd1c-c4bed4bd0e24', 'ada026bb-dc89-50d6-b88e-ea2e0a041c34', 'None', 'C', false, 2),
('f76f4f5c-9677-5ea9-83f4-411d5d06465d', 'ada026bb-dc89-50d6-b88e-ea2e0a041c34', 'About 500, but not exactly, because decay is random', 'D', true, 3),
('8a61593e-f94c-53b2-a4e9-e24fc6956734', '00e1988d-5f33-5174-b27f-26cdaf89df3d', 'Q, because it lasts longer', 'A', false, 0),
('e803d187-3c7e-5acf-80ce-c7355c8ba96f', '00e1988d-5f33-5174-b27f-26cdaf89df3d', 'P, because it has the larger decay constant', 'B', true, 1),
('21b48627-6990-5b21-9f83-f7841962a380', '00e1988d-5f33-5174-b27f-26cdaf89df3d', 'They have equal activities', 'C', false, 2),
('8c9f6dfb-c84e-55cc-ba2b-39a08cf5f694', '00e1988d-5f33-5174-b27f-26cdaf89df3d', 'It depends on their masses', 'D', false, 3),
('c35b58d6-3747-5525-8e15-8effc9b2bf9f', '46c59027-162f-5560-bb15-8359a95e5ce2', 'One half', 'A', false, 0),
('22fe14ef-70a2-5534-aee7-b77b88161d11', '46c59027-162f-5560-bb15-8359a95e5ce2', 'Three quarters', 'B', false, 1),
('549f2f3c-96d2-50b8-8368-392398c1a6f8', '46c59027-162f-5560-bb15-8359a95e5ce2', 'One quarter', 'C', true, 2),
('4acc6d52-6fd5-5876-a65a-22cde87c828a', '46c59027-162f-5560-bb15-8359a95e5ce2', 'One eighth', 'D', false, 3),
('22415117-983c-5d9f-9e4a-b952c16db597', 'f7d194b2-e1dd-526f-abc2-3531d2a62a19', 'Decay is random: one nucleus may decay at any time; half-life is a statistical average for many nuclei', 'A', true, 0),
('ca4dfcfe-3a58-5e1b-a787-1600c6010c77', 'f7d194b2-e1dd-526f-abc2-3531d2a62a19', 'A single nucleus never decays', 'B', false, 1),
('3960a90b-a42a-5ac4-b5ac-09c29fe26906', 'f7d194b2-e1dd-526f-abc2-3531d2a62a19', 'A single nucleus decays after exactly one half-life', 'C', false, 2),
('a0dd3467-407c-5e39-9ee6-77338261c8ed', 'f7d194b2-e1dd-526f-abc2-3531d2a62a19', 'Single nuclei cannot be detected', 'D', false, 3),
