('1ca2a593-fdb0-5171-afa1-2f79ddce7160', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 8, 8, 'What is the shape of a graph of activity against time for a radioactive sample?', NULL, 1, 'multiple_choice'::answer_type, 'An exponential decay curve that approaches zero', NULL, false, NULL, false, NULL, 'Equal fractions decay in equal times. Mark scheme (1 mark). B1: C (An exponential decay curve that approaches zero).', 1, NULL, NULL),
('d34b9d36-73e5-5b9c-bfa7-db03b5108e2d', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 9, 9, 'A graph of ln(activity) against time for a source is a straight line of gradient −0.035 s⁻¹. Calculate the half-life.', NULL, 1, 'numeric'::answer_type, '19.8', 's', false, NULL, false, NULL, 'λ = 0.035 s⁻¹. t½ = 0.693 ÷ 0.035 = 19.8 s. Mark scheme (2 marks). C1: λ = −gradient, then t½ = ln 2/λ. A1: t½ = 19.8 s.', 2, NULL, NULL),
('88db2d52-53cd-52ff-976d-cd09f5cbd8ae', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 10, 10, 'On a graph of N against t, what does the gradient at a point represent?', NULL, 1, 'multiple_choice'::answer_type, 'Minus the activity at that time', NULL, false, NULL, false, NULL, 'The gradient is dN/dt, the rate of change of N, which equals −A = −λN. Mark scheme (1 mark). B1: A (Minus the activity at that time).', 1, NULL, NULL),
