('1a294752-81c4-56c2-ac85-036602452612', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 28, 28, 'After 75 s, what is the activity of a source that started at 2400 Bq, if its half-life is 25 s?', NULL, 2, 'numeric'::answer_type, '300', 'Bq', false, NULL, false, NULL, '75 ÷ 25 = 3 half-lives: A = 2400 × (1/2)³ = 300 Bq. Mark scheme (3 marks). C1: number of half-lives. C1: (½)³. A1: A = 300 Bq.', 3, NULL, NULL),
('982012e7-61af-563f-bfb7-3cd71e5052cd', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 29, 29, 'An isotope has a half-life of 12 s. How long does it take for the activity to fall to one sixteenth of its starting value?', NULL, 2, 'numeric'::answer_type, '48', 's', false, NULL, false, NULL, '1/16 = (1/2)⁴: t = 4 × 12 = 48 s. Mark scheme (3 marks). C1: four half-lives. C1: value. A1: t = 48 s.', 3, NULL, NULL),
('c4b98eb4-4a4f-503a-906b-5cd440f1338a', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 30, 30, 'Background radiation is not subtracted before ln(count rate) is plotted against time. How does this affect the graph?', NULL, 2, 'multiple_choice'::answer_type, 'At long times the points level off above the straight line', NULL, false, NULL, false, NULL, 'The count rate approaches the background, not zero. Mark scheme (3 marks). C1: background constant. C1: graph flattens. A1: C (At long times the points level off above the straight line).', 3, NULL, NULL),
('bb240fa4-0052-5ad7-8fcc-1f9d169ef7c1', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 31, 31, 'An activity follows A = A₀e^(−λt) with A₀ = 500 Bq and λ = 0.0231 s⁻¹. Calculate A at t = 60 s.', NULL, 2, 'numeric'::answer_type, '125', 'Bq', false, NULL, false, NULL, 'A = 500 × e^(−0.0231 × 60) = 125 Bq. Mark scheme (3 marks). C1: substitution. C1: value. A1: A = 125 Bq.', 3, NULL, NULL),
('5425e038-9a75-54f9-af09-e9947075c218', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 32, 32, 'A graph of ln(count rate / counts per minute) against time t (in minutes) has an intercept of 6.9 and a gradient of −0.115 min⁻¹. Calculate the count rate at t = 20 min, in counts per minute.', NULL, 2, 'numeric'::answer_type, '99.48', 'counts per minute', false, NULL, false, NULL, 'ln C = 6.9 − 0.115 × 20 = 4.6, so C = e^(6.9 − 0.115 × 20) = 99.5 counts per minute. Mark scheme (4 marks). C1: equation of line. C1: ln C at 20 min. C1: C = e^(ln C). A1: C = 99.5 counts per minute.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg28174330-t fg28174330-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg28174330-t">ln C against time</title><desc id="fg28174330-d">Straight-line graph of the natural log of count rate against time, with intercept 6.9 and gradient −0.115 min⁻¹.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="113.5" y1="34" x2="113.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="292.5" y1="34" x2="292.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="113.5" y1="242" x2="113.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="113.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="203" y1="242" x2="203" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="203" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20</text><line x1="292.5" y1="242" x2="292.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="292.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">30</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">40</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="190" x2="24" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="138" x2="24" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="86" x2="24" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / min</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">ln (C / min⁻¹)</text><polyline points="24,62.6 382,182.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Straight-line graph of the natural log of count rate against time, with intercept 6.9 and gradient −0.115 min⁻¹.'),
('2588c558-0775-51de-9122-5371f6af108c', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 33, 33, 'On an activity–time curve, the time for the activity to halve is measured starting from different points on the curve. What is found?', NULL, 2, 'multiple_choice'::answer_type, 'The same half-life wherever one starts', NULL, false, NULL, false, NULL, 'Exponential decay has a constant halving time. Mark scheme (3 marks). C1: exponential. C1: constant t½. A1: A (The same half-life wherever one starts).', 3, NULL, NULL),
('7b72ea97-e40d-58ef-a1e6-676b29edd157', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 34, 34, 'The activity of a sample falls by 20% in 10 minutes. Calculate the decay constant in s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.719e-4', 's⁻¹', false, NULL, false, NULL, '0.80 = e^(−λ × 600), so λ = ln(1 ÷ 0.80) ÷ 600 = 3.72 × 10⁻⁴ s⁻¹. Mark scheme (3 marks). C1: A/A₀ = 0.80. C1: take logs. A1: λ = 3.72 × 10⁻⁴ s⁻¹.', 3, NULL, NULL),
('c0ae7454-afb3-580f-8a3b-64df264dda9b', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 35, 35, 'What fraction of a sample remains after a time equal to 2.5 half-lives?', NULL, 2, 'numeric'::answer_type, '0.1768', NULL, false, NULL, false, NULL, 'Fraction = 0.5^2.5 = 0.177. Mark scheme (3 marks). C1: (½)ⁿ with n = 2.5. C1: value. A1: fraction = 0.177.', 3, NULL, NULL),
('1b3ae7f3-e51a-52c8-bbd5-3a9d9cda295c', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 36, 36, 'Which graph for a radioactive sample is a straight line through the origin?', NULL, 2, 'multiple_choice'::answer_type, 'Activity against number of undecayed nuclei', NULL, false, NULL, false, NULL, 'A = λN, so activity is directly proportional to the number of undecayed nuclei. Mark scheme (3 marks). C1: A = λN. C1: proportional. A1: D (Activity against number of undecayed nuclei).', 3, NULL, NULL),
('d52172dd-0cea-5ec7-86f0-baec3d20c88a', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 37, 37, 'How many whole half-lives must pass before the activity of a source falls below 1% of its starting value?', NULL, 2, 'numeric'::answer_type, '7', NULL, false, NULL, false, NULL, '(1/2)⁶ = 0.0156, so 1.6% remains after 6 half-lives; (1/2)⁷ = 0.00781, so 0.78% remains after 7. The number is 6 + 1 = 7. Mark scheme (3 marks). C1: (½)⁶ > 0.01. C1: (½)⁷ < 0.01. A1: n = 7.', 3, NULL, NULL),
('0d2c3e24-fca5-56ba-9b29-de4b9bc1adef', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 38, 38, 'The raw count rate near a source is 300 counts per minute, including a background of 20 counts per minute. The source has a half-life of 5 minutes. What raw count rate is expected 10 minutes later, in counts per minute?', NULL, 2, 'numeric'::answer_type, '90', 'counts per minute', false, NULL, false, NULL, 'Corrected rate = 300 − 20 = 280; after two half-lives 280 ÷ 4 = 70; raw = 70 + 20 = 90 counts per minute. Mark scheme (3 marks). C1: correct for background. C1: two half-lives then add background. A1: count rate = 90 counts per minute.', 3, NULL, NULL),
('1d778e8c-4124-5a1c-a21c-04eec89c5a8f', 'aae53119-5afd-4055-b81b-60e6244772d7', '0d4f60c0-0c46-45a6-886d-ead834200dc8', 'a-level', '29.7', '9702 coursebook 29.7 · Decay graphs and equations', 39, 39, 'The tangent to an activity–time curve at t = 0 meets the time axis at t = 50 s. The intercept equals 1/λ. Calculate the half-life.', NULL, 2, 'numeric'::answer_type, '34.66', 's', false, NULL, false, NULL, '1/λ = 50 s, so t½ = 0.693 × 50 = 34.7 s. Mark scheme (3 marks). C1: λ = 1/50. C1: t½ = ln 2/λ. A1: t½ = 34.7 s.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg8da4f3c1-t fg8da4f3c1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8da4f3c1-t">Tangent to a decay curve</title><desc id="fg8da4f3c1-d">Graph of activity against time with the tangent at t = 0 drawn dashed; the tangent meets the time axis at t = 50 s.</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="144.2" y1="34" x2="144.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="252.3" y1="34" x2="252.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="360.4" y1="34" x2="360.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="147.5" x2="382" y2="147.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="52.9" x2="382" y2="52.9" style="stroke:var(--fig-grid,#d1d5db);stroke-wid