INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('de3bb12f-227b-57ab-b441-4a029e07e13b', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 6, 6, 'Radon-222 has a half-life of 3.8 days. Calculate its decay constant in s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.111e-6', 's⁻¹', false, NULL, false, NULL, 't½ = 3.8 × 86400 = 3.283 × 10⁵ s. λ = 0.693 ÷ 3.283 × 10⁵ = 2.11 × 10⁻⁶ s⁻¹. Mark scheme (2 marks). C1: λ = ln 2/t½ with t½ in s. A1: λ = 2.11 × 10⁻⁶ s⁻¹.', 2, NULL, NULL),
('8d160189-d434-5ee2-8681-0646f8ddebb4', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 7, 7, 'Which equation links the decay constant and the half-life?', NULL, 1, 'multiple_choice'::answer_type, 'λ = ln 2 ÷ t½', NULL, false, NULL, false, NULL, 'Putting N = N₀/2 into N = N₀e^(−λt) gives λt½ = ln 2 ≈ 0.693. Mark scheme (1 mark). B1: C (λ = ln 2 ÷ t½).', 1, NULL, NULL),
('06acdc90-ad45-57dd-b01b-8aad8f9d9ad6', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 8, 8, 'An isotope has a decay constant of 1.2 × 10⁻⁴ s⁻¹. Calculate its half-life.', NULL, 1, 'numeric'::answer_type, '5776', 's', false, NULL, false, NULL, 't½ = 0.693 ÷ 1.2 × 10⁻⁴ = 5780 s. Mark scheme (2 marks). C1: t½ = ln 2/λ. A1: t½ = 5780 s.', 2, NULL, NULL),
('b87ff463-dda6-51ce-9e65-051f636ac628', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 9, 9, 'An isotope has a large decay constant. What does this tell you?', NULL, 1, 'multiple_choice'::answer_type, 'It has a short half-life', NULL, false, NULL, false, NULL, 't½ = ln 2/λ, so a large λ gives a short half-life. Mark scheme (1 mark). B1: A (It has a short half-life).', 1, NULL, NULL),
('174f452b-6e87-5d2f-a642-39c9628605af', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 10, 10, 'A short-lived isotope has a half-life of 30 s. Calculate its decay constant.', NULL, 1, 'numeric'::answer_type, '0.0231', 's⁻¹', false, NULL, false, NULL, 'λ = 0.693 ÷ 30 = 0.0231 s⁻¹. Mark scheme (2 marks). C1: λ = ln 2/t½. A1: λ = 0.0231 s⁻¹.', 2, NULL, NULL),
('c3678a41-cf49-53c1-bc8d-77ac808a2d53', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 11, 11, 'What is the unit of the decay constant when time is measured in hours?', NULL, 1, 'multiple_choice'::answer_type, 'h⁻¹', NULL, false, NULL, false, NULL, 'λ is a probability per unit time. Mark scheme (1 mark). B1: D (h⁻¹).', 1, NULL, NULL),
('c5f0c104-c5de-55f9-b16f-f202191d690f', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 12, 12, 'An isotope has a decay constant of 0.10 min⁻¹. Calculate its half-life in minutes.', NULL, 1, 'numeric'::answer_type, '6.931', 'min', false, NULL, false, NULL, 't½ = 0.693 ÷ 0.10 = 6.93 min. Mark scheme (2 marks). C1: t½ = ln 2/λ. A1: t½ = 6.93 min.', 2, NULL, NULL),
('a4a85ce5-57bf-5e82-a278-f8612c26fad0', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 13, 13, 'How are the decay constant and the half-life related?', NULL, 1, 'multiple_choice'::answer_type, 'They are inversely proportional', NULL, false, NULL, false, NULL, 'λ × t½ = ln 2, a constant. Mark scheme (1 mark). B1: B (They are inversely proportional).', 1, NULL, NULL),
('6355f900-11e3-5b44-a518-dc547dbf615f', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 14, 14, 'Carbon-14 has a half-life of 5730 years (1 year = 3.16 × 10⁷ s). Calculate its decay constant in units of 10⁻¹² s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.828', '10⁻¹² s⁻¹', false, NULL, false, NULL, 't½ = 5730 × 3.16 × 10⁷ = 1.811 × 10¹¹ s. λ = 0.693 ÷ 1.811 × 10¹¹ = 3.83 × 10⁻¹² s⁻¹. Mark scheme (2 marks). C1: years to s, then λ. A1: λ = 3.83 × 10⁻¹² s⁻¹.', 2, NULL, NULL),
('2a785241-721a-5912-b117-09eb37cabe32', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 15, 15, 'Isotope P has a half-life of 10 min and isotope Q a half-life of 40 min. What is (decay constant of P) ÷ (decay constant of Q)?', NULL, 1, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'λ = ln 2/t½, so λ is inversely proportional to t½: 40 ÷ 10 = 4. Mark scheme (1 mark). B1: C (4).', 1, NULL, NULL),
('65e642e6-a59d-53ae-b6a0-4c9c00390e6e', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 16, 16, 'A sample of 1.0 × 10¹⁰ nuclei has a half-life of 100 s. Calculate its activity.', NULL, 1, 'numeric'::answer_type, '6.931e7', 'Bq', false, NULL, false, NULL, 'λ = 0.693 ÷ 100 = 6.93 × 10⁻³ s⁻¹. A = 6.93 × 10⁻³ × 1.0 × 10¹⁰ = 6.93 × 10⁷ Bq. Mark scheme (2 marks). C1: λ then A = λN. A1: A = 6.93 × 10⁷ Bq.', 2, NULL, NULL),
('2ed4127a-dd56-5397-acf3-b87853c2e9bc', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 17, 17, 'If the decay constant of an isotope were doubled, what would happen to its half-life?', NULL, 1, 'multiple_choice'::answer_type, 'It would halve', NULL, false, NULL, false, NULL, 't½ = ln 2/λ, so doubling λ halves the half-life. Mark scheme (1 mark). B1: A (It would halve).', 1, NULL, NULL),
('59fb9869-7ccf-51fc-8b4a-2eaa1e2763a2', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 18, 18, 'A source of half-life 2.0 hours has an activity of 1000 Bq. Calculate the number of undecayed nuclei.', NULL, 1, 'numeric'::answer_type, '1.039e7', NULL, false, NULL, false, NULL, 'λ = 0.693 ÷ 7200 = 9.627 × 10⁻⁵ s⁻¹. N = 1000 ÷ 9.627 × 10⁻⁵ = 1.04 × 10⁷. Mark scheme (2 marks). C1: λ in s⁻¹ then N = A/λ. A1: N = 1.04 × 10⁷.', 2, NULL, NULL),
('30403e63-6bd3-5744-9456-6accb4298cf3', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 19, 19, 'Isotope X has λ = 0.020 s⁻¹ and isotope Y has λ = 0.0050 s⁻¹. Calculate (half-life of Y) ÷ (half-life of X).', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 't½ ∝ 1/λ: ratio = 0.020 ÷ 0.0050 = 4.0. Mark scheme (1 mark). A1: ratio = 4.0.', 1, NULL, NULL),
('4811f5d9-63b8-5816-be72-d9ae453161ed', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 20, 20, 'Strontium-90 has a half-life of 28.8 years (1 year = 3.16 × 10⁷ s) and a molar mass of 0.090 kg mol⁻¹. Calculate the activity of 1.0 g of it. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '5.094e12', 'Bq', false, NULL, false, NULL, 'N = 1.0 × 10⁻³ ÷ 0.090 × 6.02 × 10²³ = 6.689 × 10²¹. λ = 0.693 ÷ (28.8 × 3.16 × 10⁷) = 7.616 × 10⁻¹⁰ s⁻¹. A = 7.616 × 10⁻¹⁰ × 6.689 × 10²¹ = 5.09 × 10¹² Bq. Mark scheme (3 marks). C1: N. C1: λ in s⁻¹. A1: A = 5.09 × 10¹² Bq.', 3, NULL, NULL),
('2849b33b-7ddd-5df5-83ec-5221c0bf6759', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 21, 21, 'A source containing 4.0 × 10¹⁰ undecayed nuclei has an activity of 2.0 × 10⁵ Bq. Calculate the half-life.', NULL, 2, 'numeric'::answer_type, '1.386e5', 's', false, NULL, false, NULL, 'λ = 2.0 × 10⁵ ÷ 4.0 × 10¹⁰ = 5.0 × 10⁻⁶ s⁻¹. t½ = 0.693 ÷ 5.0 × 10⁻⁶ = 1.39 × 10⁵ s. Mark scheme (3 marks). C1: λ = A/N. C1: t½ = ln 2/λ. A1: t½ = 1.39 × 10⁵ s.', 3, NULL, NULL),
('f4e1e104-438e-559e-acf0-02895c2615c6', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 22, 22, 'An isotope has a decay constant of 0.0050 s⁻¹. What fraction of a sample remains after 400 s?', NULL, 2, 'numeric'::answer_type, '0.1353', NULL, false, NULL, false, NULL, 'N/N₀ = e^(−0.0050 × 400) = e^(−2.0) = 0.135. Mark scheme (4 marks). C1: N = N₀e^(−λt). C1: λt = 2.0. C1: value. A1: fraction = 0.135.', 4, NULL, NULL),
('251ccc60-c4ee-5388-a248-ad4a7525201a', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 23, 23, 'Which half-life is most suitable for a radioactive tracer injected into a patient for a scan?', NULL, 2, 'multiple_choice'::answer_type, 'A few hours', NULL, false, NULL, false, NULL, 'Long enough to do the scan, short enough to limit the dose. Mark scheme (3 marks). C1: long enough for scan. C1: short enough to limit dose. A1: D (A few hours).', 3, NULL, NULL),
('0233e8b5-3f53-572f-89dc-14ae4cb0143d', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 24, 24, 'An isotope has a half-life of 6.0 hours. How long does it take for 90% of a sample to decay, in seconds?', NULL, 2, 'numeric'::answer_type, '71754', 's', false, NULL, false, NULL, '0.10 = e^(−λt), so t = ln 10 ÷ λ = 6.0 × 3600 × ln 10 ÷ ln 2 = 7.18 × 10⁴ s. Mark scheme (3 marks). C1: 10% remains. C1: t = t½ ln 10/ln 2. A1: t = 7.18 × 10⁴ s.', 3, NULL, NULL),
('1a94494c-3a10-5377-864d-03c035f1d489', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 25, 25, 'Samples of isotopes A (half-life 2.0 h) and B (half-life 6.0 h) contain equal numbers of nuclei. Calculate (activity of A) ÷ (activity of B).', NULL, 2, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, 'A = λN and λ ∝ 1/t½: ratio = 6.0 ÷ 2.0 = 3.0. Mark scheme (3 marks). C1: A ∝ λ for equal N. C1: λ ∝ 1/t½. A1: ratio = 3.0.', 3, NULL, NULL),
('501fec45-0aa8-5ede-8960-23e531602c1b', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 26, 26, 'Phosphorus-32 has a half-life of 14.3 days. A sample has an activity of 2.0 MBq. Calculate its activity after 30 days, in MBq.', NULL, 2, 'numeric'::answer_type, '0.4672', 'MBq', false, NULL, false, ARRAY['4.672e5']::text[], 'A = 2.0 × 0.5^(30 ÷ 14.3) = 0.467 MBq. Mark scheme (4 marks). C1: t/t½. C1: (½)^(t/t½). C1: value. A1: A = 0.467 MBq.', 4, NULL, NULL),
('1bdc4768-5803-58d9-83d9-a4a84ae47a5a', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 27, 27, 'A sample of an isotope is cut in half. What happens to the half-life of each piece?', NULL, 2, 'multiple_choice'::answer_type, 'It is unchanged', NULL, false, NULL, false, NULL, 'Half-life is set by λ, a property of the nucleus. Mark scheme (3 marks). C1: t½ = ln 2/λ. C1: independent of amount. A1: B (It is unchanged).', 3, NULL, NULL),
('5156df94-b943-5522-958e-c00236f64ba5', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 28, 28, 'A count rate falls from 400 to 280 counts s⁻¹ in 10 s (background negligible). Calculate the decay constant.', NULL, 2, 'numeric'::answer_type, '0.03567', 's⁻¹', false, NULL, false, NULL, 'λ = ln(400 ÷ 280) ÷ 10 = 0.0357 s⁻¹. Mark scheme (3 marks). C1: C = C₀e^(−λt). C1: take logs. A1: λ = 0.0357 s⁻¹.', 3, NULL, NULL),
('4dff6035-9063-54f9-89aa-f0c9feb056fe', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 29, 29, 'A count rate falls from 400 to 280 counts s⁻¹ in 10 s (background negligible). Calculate the half-life.', NULL, 2, 'numeric'::answer_type, '19.43', 's', false, NULL, false, NULL, 'λ = ln(400 ÷ 280) ÷ 10 = 0.03567 s⁻¹. t½ = 0.693 ÷ 0.03567 = 19.4 s. Mark scheme (3 marks). C1: λ. C1: t½ = ln 2/λ. A1: t½ = 19.4 s.', 3, NULL, NULL),
('59309bd5-e459-586f-85c3-b2293c87426c', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 30, 30, 'What does a decay constant of 0.010 s⁻¹ mean for a single nucleus?', NULL, 2, 'multiple_choice'::answer_type, 'It has a 1% chance of decaying in the next second', NULL, false, NULL, false, NULL, 'λ is the probability of decay per unit time. Mark scheme (3 marks). C1: probability. C1: per second. A1: C (It has a 1% chance of decaying in the next second).', 3, NULL, NULL),
('9995de25-1864-5ddc-8025-d768a2fc6edc', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 31, 31, 'A sample contains 1.0 × 10¹² nuclei of an isotope with a half-life of 1.0 hour. How many decay in the next second?', NULL, 2, 'numeric'::answer_type, '1.925e8', NULL, false, NULL, false, NULL, 'λ = 0.693 ÷ 3600 = 1.925 × 10⁻⁴ s⁻¹. Decays = λN = 1.925 × 10⁻⁴ × 1.0 × 10¹² = 1.93 × 10⁸. Mark scheme (3 marks). C1: λ in s⁻¹. C1: λN. A1: decays = 1.93 × 10⁸.', 3, NULL, NULL),
('07473973-7b87-53db-89e3-df086f2beac6', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 32, 32, 'An isotope has a half-life of 2.0 minutes. How long does it take for the activity to fall by a factor of 1000, in s?', NULL, 2, 'numeric'::answer_type, '1196', 's', false, NULL, false, NULL, 't = t½ × ln 1000 ÷ ln 2 = 120 × ln 1000 ÷ ln 2 = 1200 s. Mark scheme (4 marks). M1: e^(−λt) = 1/1000. C1: λ. C1: t. A1: t = 1200 s.', 4, NULL, NULL),
('22b0e5b3-def3-5253-8451-e92f75bb88b5', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 33, 33, 'After three half-lives, what fraction of the original nuclei have decayed?', NULL, 2, 'multiple_choice'::answer_type, '7/8', NULL, false, NULL, false, NULL, '(1/2)³ = 1/8 remain. Mark scheme (3 marks). C1: 1/8 remain. C1: 1 − 1/8. A1: A (7/8).', 3, NULL, NULL),
('affbe196-b079-5934-b133-1e4c352e0336', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 34, 34, 'One mole of an isotope with a half-life of 1.0 × 10⁴ s is prepared. Calculate its initial activity. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '4.173e19', 'Bq', false, NULL, false, NULL, 'λ = 0.693 ÷ 1.0 × 10⁴ = 6.93 × 10⁻⁵ s⁻¹. A = 6.93 × 10⁻⁵ × 6.02 × 10²³ = 4.17 × 10¹⁹ Bq. Mark scheme (3 marks). C1: λ. C1: A = λN_A. A1: A = 4.17 × 10¹⁹ Bq.', 3, NULL, NULL),
('3c277a76-5c94-5463-9cc1-625dbe75d785', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 35, 35, 'Polonium-210 has a decay constant of 5.8 × 10⁻⁸ s⁻¹. Calculate its half-life in days.', NULL, 2, 'numeric'::answer_type, '138.3', 'days', false, NULL, false, NULL, 't½ = 0.693 ÷ 5.8 × 10⁻⁸ = 1.195 × 10⁷ s. In days: 1.195 × 10⁷ ÷ 86400 = 138. Mark scheme (3 marks). C1: t½ in s. C1: s to days. A1: t½ = 138 days.', 3, NULL, NULL),
('8b5b0b88-d8e6-5264-beef-7a91d819796c', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 36, 36, 'What shape is a graph of half-life against decay constant for different isotopes?', NULL, 2, 'multiple_choice'::answer_type, 'A curve showing inverse proportion', NULL, false, NULL, false, NULL, 't½ = ln 2/λ, so t½ is inversely proportional to λ. Mark scheme (3 marks). C1: t½ ∝ 1/λ. C1: hyperbola. A1: D (A curve showing inverse proportion).', 3, NULL, NULL),
('e91e55cb-3e33-5d75-99f1-e2d9debb4fcd', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 37, 37, 'Iodine-131 has a half-life of 8.0 days and a molar mass of 0.131 kg mol⁻¹. Calculate the mass of iodine-131 in a source of activity 1.0 MBq, in units of 10⁻¹³ kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '2.17', '10⁻¹³ kg', false, NULL, false, NULL, 'λ = 0.693 ÷ (8.0 × 86400) = 1.003 × 10⁻⁶ s⁻¹. N = 1.0 × 10⁶ ÷ 1.003 × 10⁻⁶ = 9.972 × 10¹¹. m = 9.972 × 10¹¹ ÷ 6.02 × 10²³ × 0.131 = 2.17 × 10⁻¹³ kg. Mark scheme (3 marks). C1: λ and N. C1: mass from N. A1: m = 2.17 × 10⁻¹³ kg.', 3, NULL, NULL),
('cd9f7617-c7d9-5539-a85a-cb1cc1b861e8', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 38, 38, 'A strontium-90 source (half-life 28.8 years) had an activity of 5.0 MBq in 2000. (a) Calculate the number of half-lives between 2000 and 2050. (b) Calculate the activity in 2050, in MBq.', NULL, 3, 'numeric'::answer_type, '1.501', 'MBq', false, NULL, false, ARRAY['1.501e6']::text[], '(a) 50 ÷ 28.8 = 1.736. (b) A = 5.0 × 0.5^(50 ÷ 28.8) = 1.50 MBq. Mark scheme (5 marks). C1: number of half-lives. M1: A = A₀(½)ⁿ. C1: substitution. C1: value. A1: A = 1.50 MBq.', 5, NULL, NULL),
('475fb040-e9e2-5368-9a5d-92b10a08d030', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 39, 39, 'Radium-226 has a decay constant of 1.37 × 10⁻¹¹ s⁻¹ and a molar mass of 226 g mol⁻¹. (a) Calculate the number of nuclei in 1.0 g. (b) Calculate the activity of 1.0 g, in units of 10¹⁰ Bq. (c) Calculate the half-life in years (1 year = 3.16 × 10⁷ s). Give only the answer to (b). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '3.649', '10¹⁰ Bq', false, NULL, false, NULL, '(a) N = 6.02 × 10²³ ÷ 226 = 2.664 × 10²¹. (b) A = 1.37 × 10⁻¹¹ × 2.664 × 10²¹ = 3.65 × 10¹⁰ Bq. (c) t½ = 0.693 ÷ 1.37 × 10⁻¹¹ ÷ 3.16 × 10⁷ ≈ 1601 years. Mark scheme (6 marks). C1: N. M1: A = λN. C1: value. C1: t½ in s. C1: in years. A1: A = 3.65 × 10¹⁰ Bq.', 6, NULL, NULL),
('d2de60bd-429c-560b-b6b9-cc323abbc8c3', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 40, 40, 'A sample''s activity falls from 8.0 MBq to 5.0 MBq in 6.0 hours. (a) Calculate λ in h⁻¹. (b) Calculate the half-life in hours.', NULL, 3, 'numeric'::answer_type, '8.849', 'h', false, NULL, false, NULL, '(a) λ = ln(8.0 ÷ 5.0) ÷ 6.0 = 0.07833 h⁻¹. (b) t½ = 0.693 ÷ 0.07833 = 8.85 h. Mark scheme (5 marks). M1: A = A₀e^(−λt). C1: λ. M1: t½ = ln 2/λ. C1: value. A1: t½ = 8.85 h.', 5, NULL, NULL),
('d2940b89-3f7a-5497-9f7b-6528cd916ae9', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 41, 41, 'Uranium-238 has a half-life of 4.5 × 10⁹ years. The Earth is about 4.6 × 10⁹ years old. (a) Calculate λ in year⁻¹. (b) Calculate the fraction of the Earth''s original uranium-238 that remains.', NULL, 3, 'numeric'::answer_type, '0.4924', NULL, false, NULL, false, NULL, '(a) λ = 0.693 ÷ 4.5 × 10⁹ = 1.540 × 10⁻¹⁰ year⁻¹. (b) N/N₀ = 0.5^(4.6 × 10⁹ ÷ 4.5 × 10⁹) = 0.492. Mark scheme (6 marks). C1: λ. M1: N/N₀ = e^(−λt) or (½)^(t/t½). C1: exponent. C1: value. B1: about half remains. A1: fraction = 0.492.', 6, NULL, NULL),
('cadacd94-c59f-5b40-ba39-3e573676bf8e', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 42, 42, 'Uranium-238 has a half-life of 4.5 × 10⁹ years (1 year = 3.16 × 10⁷ s) and a molar mass of 0.238 kg mol⁻¹. (a) Calculate λ in s⁻¹. (b) Calculate the mass of uranium-238 with an activity of 1.0 Bq, in units of 10⁻⁸ kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '8.111', '10⁻⁸ kg', false, NULL, false, NULL, '(a) λ = 0.693 ÷ (4.5 × 10⁹ × 3.16 × 10⁷) = 4.874 × 10⁻¹⁸ s⁻¹. (b) N = 1.0 ÷ 4.874 × 10⁻¹⁸ = 2.052 × 10¹⁷; m = 2.052 × 10¹⁷ ÷ 6.02 × 10²³ × 0.238 = 8.11 × 10⁻⁸ kg. Mark scheme (5 marks). C1: λ. C1: N = A/λ. M1: mass from N. C1: value. A1: m = 8.11 × 10⁻⁸ kg.', 5, NULL, NULL),
('29ce24f7-52ad-55b0-8cfc-f830231ab86f', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 43, 43, 'Iodine-131 has a physical half-life of 8.0 days, but the body also removes iodine with a biological half-life of 24 days. The effective decay constant is the sum of the two decay constants. (a) Calculate both decay constants in day⁻¹. (b) Calculate the effective half-life in days.', NULL, 3, 'numeric'::answer_type, '6', 'days', false, NULL, false, NULL, '(a) λp = 0.693 ÷ 8.0 = 0.08664 day⁻¹; λb = 0.693 ÷ 24 = 0.02888 day⁻¹. (b) t½ = 0.693 ÷ (0.08664 + 0.02888) = 6.00 days. Mark scheme (6 marks). C1: physical λ. C1: biological λ. M1: add decay constants. C1: t½ = ln 2/λ(eff). C1: value. A1: t½(eff) = 6.00 days.', 6, NULL, NULL),
('54afa00d-4639-54f5-ac6e-38543884c30c', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 44, 44, 'In living matter, 1 carbon atom in 1.0 × 10¹² is carbon-14 (λ = 3.83 × 10⁻¹² s⁻¹). Carbon has a molar mass of 12 g mol⁻¹. (a) Calculate the number of carbon-14 atoms in 1.0 g of carbon. (b) Calculate the activity of 1.0 g of carbon. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.1921', 'Bq', false, NULL, false, NULL, '(a) N = 6.02 × 10²³ ÷ 12 × 1.0 × 10⁻¹² = 5.017 × 10¹⁰. (b) A = 3.83 × 10⁻¹² × 5.017 × 10¹⁰ = 0.192 Bq. Mark scheme (5 marks). C1: atoms of carbon. C1: fraction C-14. M1: A = λN. C1: value. A1: A = 0.192 Bq.', 5, NULL, NULL),
('c40ddaa9-95c6-58ff-96b3-7c81af29daff', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 45, 45, 'Plutonium-239 has a half-life of 2.4 × 10⁴ years. (a) Calculate λ in year⁻¹. (b) Calculate the time for 1.0 kg of plutonium-239 to lose 1.0 g by decay, in years.', NULL, 3, 'numeric'::answer_type, '34.64', 'years', false, NULL, false, NULL, '(a) λ = 0.693 ÷ 2.4 × 10⁴ = 2.888 × 10⁻⁵ year⁻¹. (b) 0.999 = e^(−λt), so t = ln(1 ÷ 0.999) ÷ 2.888 × 10⁻⁵ = 34.6 years. Mark scheme (6 marks). C1: λ. M1: N/N₀ = 0.999. C1: take logs. C1: substitution. C1: value. A1: t = 34.6 years.', 6, NULL, NULL),
('583659ea-b3b7-505a-a124-4a70cc8e784f', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 46, 46, 'Cobalt-60 has a half-life of 5.27 years. (a) Calculate the probability that a particular cobalt-60 nucleus survives one year. (b) Calculate the probability that it decays within one year.', NULL, 3, 'numeric'::answer_type, '0.1232', NULL, false, NULL, false, NULL, '(a) Survival = 0.5^(1 ÷ 5.27) = 0.8768. (b) Decay = 1 − 0.8768 = 0.123. Mark scheme (5 marks). M1: survival = (½)^(t/t½). C1: value. M1: 1 − survival. C1: value. A1: probability = 0.123.', 5, NULL, NULL),
('b51602ff-0804-5aec-9c4c-5a4dacf962ed', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 47, 47, 'A rock contains potassium-40 (half-life 1.25 × 10⁹ years), which decays to argon-40 that is trapped in the rock. There is now 0.50 argon-40 atom for every potassium-40 atom. (a) Show that the fraction of the original potassium remaining is 1/1.5. (b) Calculate the age of the rock, in units of 10⁸ years.', NULL, 3, 'numeric'::answer_type, '7.312', '10⁸ years', false, NULL, false, NULL, '(a) For every 1 K now there were 1 + 0.50 = 1.5 originally. (b) t = t½ × ln 1.5 ÷ ln 2 = 1.25 × 10⁹ × ln 1.5 ÷ ln 2 = 7.31 × 10⁸ years. Mark scheme (6 marks). B1: N₀ = 1.5N. M1: N/N₀ = e^(−λt). C1: take logs. C1: substitution. C1: value. A1: age = 7.31 × 10⁸ years.', 6, NULL, NULL),
('4ec54cf6-8a21-516d-9294-4ae18d5e7ddb', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 48, 48, 'Isotopes P (half-life 3.0 h) and Q (half-life 9.0 h) are present in equal numbers at t = 0. (a) Calculate the ratio of their activities at t = 0. (b) Calculate (N of P) ÷ (N of Q) after 9.0 hours.', NULL, 3, 'numeric'::answer_type, '0.25', NULL, false, NULL, false, NULL, '(a) A_P/A_Q = λ_P/λ_Q = 9.0 ÷ 3.0 = 3.0. (b) (1/2)³ ÷ (1/2)¹ = 0.250. Mark scheme (5 marks). C1: activity ratio. M1: three and one half-lives. C1: ratio of fractions. C1: value. A1: ratio = 0.250.', 5, NULL, NULL),
('dec786f4-f5dc-534f-a639-2c274ccbc190', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 49, 49, 'A technetium-99m generator is set up so that a dose of 600 MBq is ready at 8 a.m. The half-life is 6.0 h. (a) Calculate the activity at 2 p.m. (b) Calculate the time after 8 a.m. at which the activity falls to 100 MBq, in hours. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '15.51', 'h', false, NULL, false, NULL, '(a) 300 MBq. (b) The activity falls by a factor of 6, so t = 6.0 × ln 6 ÷ ln 2 = 15.5 h. Mark scheme (6 marks). C1: one half-life. M1: exponential equation. C1: λ. C1: take logs. C1: value. A1: t = 15.5 h.', 6, NULL, NULL),
('de5bd29b-b06c-5344-9030-6e824e66bfdd', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '29.8', '9702 coursebook 29.8 · Decay constant λ and half-life', 50, 50, 'Nuclei of an isotope have a mean lifetime τ = 1/λ. (a) Show that t½ = τ ln 2. (b) An isotope has τ = 2.0 × 10³ s. Calculate its half-life.', NULL, 3, 'numeric'::answer_type, '1386', 's', false, NULL, false, NULL, '(a) t½ = ln 2/λ = τ ln 2. (b) t½ = 2.0 × 10³ × 0.693 = 1390 s. Mark scheme (5 marks). B1: t½ = ln 2/λ. M1: τ = 1/λ. C1: substitution. C1: value. A1: t½ = 1390 s.', 5, NULL, NULL)
